window.kycMeasures = {"AK":{"has":true,"by":"Alaska Division of Elections","read":"2026-10-19","list":{"url":"https://www.elections.alaska.gov/petitions-and-ballot-measures/","title":"Petitions and Ballot Measures - Division of Elections"},"guide":{"url":"https://www.elections.alaska.gov/publications/","title":"2026 General Official Election Pamphlet (Alaska Division of Elections)"},"measures":[{"designation":"Ballot Measure No. 2","title":"24ESEG - An Act Restoring Political Party Primaries, Ending Ranked-Choice General Elections, and Repealing Recent Campaign Finance Laws","text":"This act would get rid of open primary elections, where all candidates appear on one ballot. It would also get rid of ranked-choice general elections. It would bring back political party primaries and single-choice general elections. It would also repeal certain campaign finance rules that were added by a 2020 ballot measure. Elections would occur as they did before open primaries and ranked choice voting. In the primary election, voters would choose a party’s ballot, unless prohibited by the party’s bylaws. They would only vote for candidates on that ballot. The winning candidate from each primary would be the party’s nominee. In the general election, voters would vote for only one candidate in each race. The candidate with the most votes would win. Party petitions, special runoff elections, and other processes would return. Candidates for governor and lieutenant governor would run separately in political party primaries and then together in the general election. This act would also repeal campaign finance rules that were passed in 2020. It would remove the limits on donations to joint campaigns for governor and lieutenant governor. It would remove limits and disclosure rules under current law, including for digital ads, out-of-state donations, undisclosed donations, and the true source of donations. It would change the meaning of a campaign expenditure and remove some fines. Should this initiative become law?","kind":"Statute","origin":"a citizens' petition","source":"https://www.elections.alaska.gov/election/2026/General/SampleBallots/HD1-JD1.pdf","guide":"https://www.elections.alaska.gov/election/2026/General/OEPbooks/2026%20Alaska%20General%20VP_Region%202_ENG_web.pdf#page=105"},{"designation":"Ballot Measure No. 3","title":"25USCV - An Act Addressing Voter Qualification","text":"Alaska law requires that someone must be a United States citizen and meet other requirements to vote. This act would specify that only those who are United States citizens and meet the other requirements may vote. This act would not change the requirements to vote. Should this initiative become law?","kind":"Statute","origin":"a citizens' petition","source":"https://www.elections.alaska.gov/election/2026/General/SampleBallots/HD1-JD1.pdf","guide":"https://www.elections.alaska.gov/election/2026/General/OEPbooks/2026%20Alaska%20General%20VP_Region%202_ENG_web.pdf#page=139"}]},"AL":{"has":true,"by":"Alabama Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.alabama.gov/sites/default/files/election-2026/2026GeneralElectionStateCertificationofConstitutionalAmendments.pdf","title":"State Certification of Constitutional Amendments, 2026 General Election (Alabama Secretary of State, certified 8/26/2026)"},"guide":{"url":"https://www.sos.alabama.gov/sites/default/files/sample-ballots/2026/gen/2026GeneralElectionStatewideBack.pdf","title":"Alabama Fair Ballot Commission: ballot statements for Statewide Amendments 1-4"},"measures":[{"designation":"Statewide Amendment 1","title":null,"text":"Proposing an amendment to the Constitution of Alabama of 2022, to provide for the election of a Lieutenant Governor if the Office of Lieutenant Governor becomes vacant during the first two years of a term, to authorize the Legislature to set the salary of the Lieutenant Governor and officers of the Legislature, and to require any expenditure of legislative funds for travel to be approved by a legislative officer. (Proposed by Act 2026-341)","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.alabama.gov/sites/default/files/election-2026/2026GeneralElectionStateCertificationofConstitutionalAmendments.pdf","guide":"https://www.sos.alabama.gov/sites/default/files/sample-ballots/2026/gen/2026GeneralElectionStatewideBack.pdf"},{"designation":"Statewide Amendment 2","title":null,"text":"Proposing an amendment to the Constitution of Alabama of 2022, to provide a process for the creation of a consolidated county school system by merging two or more contiguous county boards of education; to require the State Board of Education to conduct an impact study on the potential effects of the consolidation; to require publication of the impact study; to provide a procedure for protesting a proposed consolidation of two or more county school systems; and to require the State Board of Education to adopt rules. (Proposed by Act 2026-378)","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.alabama.gov/sites/default/files/election-2026/2026GeneralElectionStateCertificationofConstitutionalAmendments.pdf","guide":"https://www.sos.alabama.gov/sites/default/files/sample-ballots/2026/gen/2026GeneralElectionStatewideBack.pdf"},{"designation":"Statewide Amendment 3","title":null,"text":"Proposing an amendment to the Constitution of Alabama of 2022, to require local boards of education to adopt policies requiring each public K-12 school to recite The Pledge of Allegiance to the United States flag at the beginning of each school day; and to require local boards of education to adopt a policy authorizing student-initiated and student-led prayer. (Proposed by Act 2026-379)","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.alabama.gov/sites/default/files/election-2026/2026GeneralElectionStateCertificationofConstitutionalAmendments.pdf","guide":"https://www.sos.alabama.gov/sites/default/files/sample-ballots/2026/gen/2026GeneralElectionStatewideBack.pdf"},{"designation":"Statewide Amendment 4","title":null,"text":"Proposing an amendment to the Constitution of Alabama of 2022, to require local boards of education to adopt policies requiring each public K-12 school to broadcast or sanction the performance of the first stanza of The Star-Spangled Banner at least once per week during school hours. (Proposed by Act 2026-424)","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.alabama.gov/sites/default/files/election-2026/2026GeneralElectionStateCertificationofConstitutionalAmendments.pdf","guide":"https://www.sos.alabama.gov/sites/default/files/sample-ballots/2026/gen/2026GeneralElectionStatewideBack.pdf"}]},"AR":{"has":true,"by":"Arkansas Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.arkansas.gov/elections/initiatives-and-referenda/","title":"Initiatives and Referenda - Arkansas Secretary of State"},"measures":[{"designation":"Issue No. 1","title":"A Constitutional Amendment to be Known as \"The Citizens Only Voting Amendment\" and Providing That Only a Citizen of the United States Meeting the Qualifications of an Elector Under the Arkansas Constitution May Vote in an Election in this State.","text":"AN AMENDMENT TO THE ARKANSAS CONSTITUTION TO CREATE \"THE CITIZENS ONLY VOTING AMENDMENT\"; TO PROVIDE THAT ONLY A CITIZEN OF THE UNITED STATES MEETING THE QUALIFICATIONS OF AN ELECTOR UNDER THE ARKANSAS CONSTITUTION MAY VOTE IN AN ELECTION IN THIS STATE; AND PROVIDING THAT A PERSON WHO DOES NOT MEET THE QUALIFICATIONS OF AN ELECTOR UNDER THE ARKANSAS CONSTITUTION SHALL NOT BE PERMITTED TO VOTE IN ANY STATE OR LOCAL ELECTION HELD IN THIS STATE.","kind":"Constitutional amendment","origin":"the General Assembly","source":"http://www.sos.arkansas.gov/uploads/elections/Issue_No._1_HJR_1018_of_2026_.pdf_.pdf"},{"designation":"Issue No. 2","title":"A Constitutional Amendment to Amend Arkansas Constitution, Article 2, § 5, to Protect the Right to Keep and Bear Arms.","text":"AN AMENDMENT TO THE ARKANSAS CONSTITUTION TO PROVIDE THAT THE CITIZENS OF THE STATE OF ARKANSAS SHALL HAVE THE RIGHT TO KEEP AND BEAR ARMS FOR THEIR COMMON DEFENSE, FOR LAWFUL HUNTING AND RECREATIONAL USE, AND FOR ANY OTHER LAWFUL PURPOSE; PROVIDING THAT THE RIGHT TO KEEP AND BEAR ARMS INCLUDES WITHOUT LIMITATION THE POSSESSION AND USE OF AMMUNITION, FIREARM ACCESSORIES, AND FIREARM COMPONENTS; AND PROVIDING THAT THE RIGHT TO KEEP AND BEAR ARMS IS A NATURAL, FUNDAMENTAL, AND INDIVIDUAL RIGHT THAT SHALL NOT BE INFRINGED.","kind":"Constitutional amendment","origin":"the General Assembly","source":"http://www.sos.arkansas.gov/uploads/elections/Issue_No._2_SJR_11_of_2026_.pdf"},{"designation":"Issue No. 3","title":"A Constitutional Amendment Concerning Economic Development in the State of Arkansas; and Authorizing the General Assembly to Provide for the Creation of Economic Development Districts Within Cities, Counties, or Cooperative Areas to Promote Economic Development Within the Economic Development District.","text":"AN AMENDMENT TO THE ARKANSAS CONSTITUTION CONCERNING ECONOMIC DEVELOPMENT IN THE STATE OF ARKANSAS; AND AUTHORIZING THE GENERAL ASSEMBLY TO PROVIDE FOR THE CREATION OF ECONOMIC DEVELOPMENT DISTRICTS WITHIN CITIES, COUNTIES, OR COOPERATIVE AREAS TO PROMOTE ECONOMIC DEVELOPMENT WITHIN THE ECONOMIC DEVELOPMENT DISTRICT.","kind":"Constitutional amendment","origin":"the General Assembly","source":"http://www.sos.arkansas.gov/uploads/elections/Issue_No._3_SJR_15_of_2026_.pdf"},{"designation":"Issue No. 4","title":"Arkansas Water, Waste Disposal, and Pollution Abatement Facilities Financing Act of 2025.","text":"Shall the Arkansas Natural Resources Commission be authorized to issue general obligation bonds under the authority of the Arkansas Water, Waste Disposal, and Pollution Abatement Facilities Financing Act of 2025, for the financing and refinancing of the development of water, waste disposal, water pollution control, abatement and prevention, drainage, irrigation, flood control, and wetlands and aquatic resources projects to serve the citizens of the State of Arkansas, in total principal amount not to exceed five hundred million dollars ($500,000,000), with no more than one hundred sixty-five million dollars ($165,000,000) in total principal amount of such bonds to be issued to finance and refinance the development of irrigation facilities, in series from time to time in principal amounts not to exceed, without prior approval of the General Assembly, sixty million dollars ($60,000,000) in any two-year period beginning on July 1 of each odd-numbered year, which bonds shall be secured by a pledge of the full faith and credit of the State of Arkansas?","kind":"Bond","origin":"the General Assembly","source":"http://www.sos.arkansas.gov/uploads/elections/Issue_No._4_Act_578_of_2026_.pdf"}]},"AS":{"has":null,"by":"American Samoa Election Office","read":"2026-10-19","office":{"url":"https://www.aselectionoffice.gov/","name":"American Samoa Election Office"}},"AZ":{"has":true,"by":"Arizona Secretary of State","read":"2026-10-19","list":{"url":"https://azsos.gov/elections/ballot-measures","title":"Ballot Measures | Arizona Secretary of State"},"guide":{"url":"https://apps.azsos.gov/election/BallotMeasures/2026/2026-AZ-Publicity-Pamphlet.pdf","title":"Arizona 2026 General Election Publicity Pamphlet, November 3, 2026"},"measures":[{"designation":"Proposition 141","title":"PROHIBITS TAXES OR FEES BASED ON VEHICLE MILES TRAVELED AND LAWS MONITORING OR LIMITING VEHICLE MILES TRAVELED WITHOUT CONSENT.","text":"PROHIBITS TAXES OR FEES BASED ON VEHICLE MILES TRAVELED AND LAWS MONITORING OR LIMITING VEHICLE MILES TRAVELED WITHOUT CONSENT. A “yes” vote shall have the effect of amending the Arizona Constitution to prohibit: (1) taxes or fees based on motor vehicle miles traveled; and (2) laws or rules that monitor or limit motor vehicle miles traveled without consent. These prohibitions do not apply in certain instances to interstate commercial vehicles or to vehicles owned by the state or local governments. A “no” vote shall have the effect of maintaining the current constitutional language related to taxation.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://azsos.gov/sites/default/files/docs/2026-Ballot-Language-English-2026-0819.pdf","guide":"https://apps.azsos.gov/election/BallotMeasures/2026/2026-AZ-Publicity-Pamphlet.pdf#page=38"},{"designation":"Proposition 142","title":"ADDS FURTHER DETAILS TO THE CONSTITUTIONAL PROHIBITION AGAINST PREFERENTIAL TREATMENT OR DISCRIMINATION BY THE STATE BASED ON RACE, ETHNICITY, OR OTHER CLASSES.","text":"ADDS FURTHER DETAILS TO THE CONSTITUTIONAL PROHIBITION AGAINST PREFERENTIAL TREATMENT OR DISCRIMINATION BY THE STATE BASED ON RACE, ETHNICITY, OR OTHER CLASSES. A “yes” vote shall have the effect of amending the Arizona Constitution’s current prohibition against preferential treatment or discrimination by the state based on race, ethnicity, or other classes, to specifically prohibit: (1) compelling individuals to support preferential treatment or discrimination based on race or ethnicity as a condition of education, employment, or contract opportunities; (2) spending public money on positions in public education responsible for promoting preferential treatment or discrimination based on race or ethnicity; and (3) implementing disciplinary practices that treat students or employees differently based on race or ethnicity. Prohibited conduct includes requiring or asking an applicant, employee, student, or contractor to provide a statement in support of race-based diversity, equity, and inclusion beyond upholding the federal Equal Protection Clause or asking such a person to discuss the person’s race or ethnicity or experience with others’ race or ethnicity. The amendment contains certain exceptions for health services, legal, and other reasons. A “no” vote shall have the effect of maintaining the current prohibition in the Arizona Constitution against preferential treatment or discrimination by the state based on race, ethnicity, or other classes.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://azsos.gov/sites/default/files/docs/2026-Ballot-Language-English-2026-0819.pdf","guide":"https://apps.azsos.gov/election/BallotMeasures/2026/2026-AZ-Publicity-Pamphlet.pdf#page=56"},{"designation":"Proposition 144","title":"REQUIRES ALL VOTERS, INCLUDING VOTERS WHO VOTE BY MAIL, TO SHOW GOVERNMENT-ISSUED ID TO VOTE IN EACH ELECTION; MAKES OTHER CHANGES TO ELECTION ADMINISTRATION AND CAMPAIGN FINANCE PROHIBITIONS.","text":"REQUIRES ALL VOTERS, INCLUDING VOTERS WHO VOTE BY MAIL, TO SHOW GOVERNMENT-ISSUED ID TO VOTE IN EACH ELECTION; MAKES OTHER CHANGES TO ELECTION ADMINISTRATION AND CAMPAIGN FINANCE PROHIBITIONS. A “yes” vote shall have the effect of amending the Arizona Constitution to: (1) require voters to show proof of identity when voting in each election, including when voting by mail; (2) changing existing proof of identity requirements to limit acceptable documentation to government-issued ID; (3) require election officials to provide all voters the option to have their ballot tabulated at their voting location on election day; (4) prohibit foreign nationals from contributing or spending to influence elections in Arizona and prohibit anyone from knowingly accepting such contributions, similar to prohibitions that already exist in federal law; (5) create a new standard for judicial review of election laws under the Arizona Constitution, which may make it harder to challenge election laws; and (6) require the legislature to appropriate money necessary to implement these provisions. A “no” vote shall have the effect of maintaining current constitutional provisions governing elections.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://azsos.gov/sites/default/files/docs/2026-Ballot-Language-English-2026-0819.pdf","guide":"https://apps.azsos.gov/election/BallotMeasures/2026/2026-AZ-Publicity-Pamphlet.pdf#page=70"},{"designation":"Proposition 316","title":"RETROACTIVELY PROHIBITS LOCAL GOVERNMENTS FROM ADOPTING OR INCREASING A TAX ON GROCERIES WITHOUT VOTER APPROVAL AND SETS A MAXIMUM RATE OF 2%.","text":"RETROACTIVELY PROHIBITS LOCAL GOVERNMENTS FROM ADOPTING OR INCREASING A TAX ON GROCERIES WITHOUT VOTER APPROVAL AND SETS A MAXIMUM RATE OF 2%. A “yes” vote shall have the effect of: (1) retroactively prohibiting local governments from adopting or increasing a tax on groceries from July 1, 2025, through June 30, 2027; and (2) after that time, prohibiting local governments from adopting or increasing a tax on groceries without voter approval and limiting any new or increased tax to a maximum rate of 2%. A “no” vote shall have the effect of maintaining the current laws relating to local government taxation.","kind":"Statute","origin":"the Legislature","source":"https://azsos.gov/sites/default/files/docs/2026-Ballot-Language-English-2026-0819.pdf","guide":"https://apps.azsos.gov/election/BallotMeasures/2026/2026-AZ-Publicity-Pamphlet.pdf#page=96"},{"designation":"Proposition 317","title":"DECLARES THAT DRUG CARTELS ARE TERRORIST ORGANIZATIONS; DIRECTS THE ARIZONA DEPARTMENT OF HOMELAND SECURITY TO DO EVERYTHING IN ITS AUTHORITY TO ADDRESS DRUG CARTELS.","text":"DECLARES THAT DRUG CARTELS ARE TERRORIST ORGANIZATIONS; DIRECTS THE ARIZONA DEPARTMENT OF HOMELAND SECURITY TO DO EVERYTHING IN ITS AUTHORITY TO ADDRESS DRUG CARTELS. A “yes” vote shall have the effect of: (1) declaring drug cartels as terrorist organizations and directing the Arizona Department of Homeland Security to do everything in its authority to address threats posed by drug cartels; (2) defining “drug cartel” to mean an ongoing formal or informal association of persons engaged in human smuggling, drug trafficking, or any act defined as terrorism under Arizona law; and (3) clarifying that this measure does not support an alien’s asylum claim. A “no” vote shall have the effect of maintaining the current laws relating to terrorism and the Arizona Department of Homeland Security.","kind":"Statute","origin":"the Legislature","source":"https://azsos.gov/sites/default/files/docs/2026-Ballot-Language-English-2026-0819.pdf","guide":"https://apps.azsos.gov/election/BallotMeasures/2026/2026-AZ-Publicity-Pamphlet.pdf#page=101"},{"designation":"Proposition 318","title":"REQUIRES ALL SCHOOLS AND ATHLETIC ASSOCIATIONS TO DESIGNATE ATHLETIC TEAMS AS MALE, FEMALE, OR COED BASED ON THE BIOLOGICAL SEX OF THE ATHLETES AS DEFINED AT BIRTH; PROHIBITS THESE ENTITIES FROM AUTHORIZING USE OF PRIVATE SPACES NOT DESIGNATED FOR A PERSON’S SEX.","text":"REQUIRES ALL SCHOOLS AND ATHLETIC ASSOCIATIONS TO DESIGNATE ATHLETIC TEAMS AS MALE, FEMALE, OR COED BASED ON THE BIOLOGICAL SEX OF THE ATHLETES AS DEFINED AT BIRTH; PROHIBITS THESE ENTITIES FROM AUTHORIZING USE OF PRIVATE SPACES NOT DESIGNATED FOR A PERSON’S SEX. A “yes” vote shall have the effect of: (1) requiring private schools, public schools, and athletic associations to designate every athletic team as male, female, or coed/mixed based on sex and to prevent males from joining female teams; existing law imposes this requirement only on public schools and those competing against them; (2) prohibiting schools and athletic associations from authorizing anyone to use private spaces (such as restrooms) not designated for that individual’s sex; (3) defining “sex” as an individual’s biological status as male or female as recorded at birth on an original birth certificate; and (4) authorizing athletes to sue schools and athletic associations that knowingly violate this law. A “no” vote shall have the effect of maintaining the current laws relating to student athletics.","kind":"Statute","origin":"the Legislature","source":"https://azsos.gov/sites/default/files/docs/2026-Ballot-Language-English-2026-0819.pdf","guide":"https://apps.azsos.gov/election/BallotMeasures/2026/2026-AZ-Publicity-Pamphlet.pdf#page=106"},{"designation":"Proposition 319","title":"PROHIBITS STATE AGENCIES AND LOCAL GOVERNMENTS FROM USING PHOTO ENFORCEMENT SYSTEMS FOR TRAFFIC ENFORCEMENT UNLESS PROVIDED BY CONTRACT AS OF DECEMBER 31, 2026; REQUIRES LOCAL GOVERNMENTS TO OBTAIN VOTER APPROVAL TO CONTINUE THEIR USE.","text":"PROHIBITS STATE AGENCIES AND LOCAL GOVERNMENTS FROM USING PHOTO ENFORCEMENT SYSTEMS FOR TRAFFIC ENFORCEMENT UNLESS PROVIDED BY CONTRACT AS OF DECEMBER 31, 2026; REQUIRES LOCAL GOVERNMENTS TO OBTAIN VOTER APPROVAL TO CONTINUE THEIR USE. A “yes” vote shall have the effect of: (1) prohibiting state agencies and local governments from using photo enforcement systems to identify violators of traffic laws unless the agency or government contracts to use those systems by December 31, 2026; and (2) requiring local governments to obtain voter approval of existing photo enforcement systems at the next regular general election and every 10 years afterward to continue using photo enforcement systems. A “no” vote shall have the effect of maintaining the current laws governing photo enforcement systems.","kind":"Statute","origin":"the Legislature","source":"https://azsos.gov/sites/default/files/docs/2026-Ballot-Language-English-2026-0819.pdf","guide":"https://apps.azsos.gov/election/BallotMeasures/2026/2026-AZ-Publicity-Pamphlet.pdf#page=131"},{"designation":"Proposition 320","title":"REQUIRES CERTAIN SCHOOL DISTRICTS TO SPEND AT LEAST SIXTY PERCENT OF THEIR OPERATIONAL SPENDING ON DIRECT INSTRUCTIONAL EXPENSES AS DEFINED BY THE AUDITOR GENERAL; REDUCES CERTAIN STATE FUNDING FOR NON-COMPLIANT DISTRICTS.","text":"REQUIRES CERTAIN SCHOOL DISTRICTS TO SPEND AT LEAST SIXTY PERCENT OF THEIR OPERATIONAL SPENDING ON DIRECT INSTRUCTIONAL EXPENSES AS DEFINED BY THE AUDITOR GENERAL; REDUCES CERTAIN STATE FUNDING FOR NON-COMPLIANT DISTRICTS. A “yes” vote shall have the effect of: (1) requiring school districts with 7,500 or more students in any county or that operate in a county with 500,000 or more people to spend at least 60% of their operational spending on direct instructional expenses; (2) requiring the state Auditor General to define “operational spending” and “direct instructional expenses”; (3) requiring non-compliant school districts to gradually adjust their spending each year until they are in compliance; and (4) requiring the state Department of Education to reduce funding from the state Classroom Site Fund by 25% each year for non-compliant districts, subject to limited waivers that the state Superintendent of Public Instruction may authorize. A “no” vote shall have the effect of maintaining the current laws governing school district budgets.","kind":"Statute","origin":"the Legislature","source":"https://azsos.gov/sites/default/files/docs/2026-Ballot-Language-English-2026-0819.pdf","guide":"https://apps.azsos.gov/election/BallotMeasures/2026/2026-AZ-Publicity-Pamphlet.pdf#page=138"}]},"CA":{"has":true,"by":"California Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.ca.gov/elections/ballot-measures/qualified-ballot-measures","title":"Qualified Statewide Ballot Measures :: California Secretary of State"},"guide":{"url":"https://voterguide.sos.ca.gov/propositions/","title":"California General Election November 3, 2026 Official Voter Information Guide"},"measures":[{"designation":"Proposition 1","title":"AUTHORIZES BONDS FOR HOUSING AFFORDABILITY PROGRAMS. LEGISLATIVE STATUTE.","text":"Authorizes $11.25 billion in state general obligation bonds for housing affordability programs, including multifamily rental housing, mortgages for veterans, supportive housing, preservation of existing affordable housing, and downpayment assistance.","kind":"Bond","origin":"the Legislature","source":"https://voterguide.sos.ca.gov/propositions/1/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/1/index.htm"},{"designation":"Proposition 2","title":"INCREASES STATE’S RAINY DAY FUND. LEGISLATIVE CONSTITUTIONAL AMENDMENT.","text":"Increases California's Rainy Day Fund, approved by voters in 2014, to provide funding for education, health care, public safety, and other essential services during economic downturns.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://voterguide.sos.ca.gov/propositions/2/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/2/index.htm"},{"designation":"Proposition 3","title":"PROVIDES PERMANENT FUNDING FOR SCHOOLS AND HEALTH CARE BY EXTENDING EXISTING TAX ON HIGH INCOMES. INITIATIVE CONSTITUTIONAL AMENDMENT.","text":"Makes permanent existing voter-approved tax rates for individuals earning over $371,000 (adjusted annually for inflation). Allocates tax revenues to public education.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://voterguide.sos.ca.gov/propositions/3/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/3/index.htm"},{"designation":"Proposition 4","title":"REPEALS PROHIBITION AGAINST PUBLIC FUNDING OF ELECTION CAMPAIGNS. LEGISLATIVE STATUTE.","text":"Repeals prohibition on state and local governments offering public funding of candidate election campaigns. Public funding programs may not use funds earmarked for education, transportation, or public safety.","kind":"Statute","origin":"the Legislature","source":"https://voterguide.sos.ca.gov/propositions/4/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/4/index.htm"},{"designation":"Proposition 5","title":"CHANGES RECALL ELECTION PROCESS FOR STATEWIDE OFFICERS. LEGISLATIVE CONSTITUTIONAL AMENDMENT.","text":"Under current law, voters elect replacement candidates at the same time as the recall election. This measure instead fills recall vacancies by subsequent special election or appointment.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://voterguide.sos.ca.gov/propositions/5/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/5/index.htm"},{"designation":"Proposition 37","title":"CREATES LOAN PROGRAM FOR MIDDLE-INCOME BUYERS OF QUALIFIED NEW HOMES. INITIATIVE STATUTE.","text":"Authorizes $25 billion in bonds to offer eligible buyers fixed-rate mortgages for up to 17% of purchase price of a newly constructed home priced below about $1.5 million. Borrowers must be California residents, occupy the home, meet income limits, and pay at least 3% down. Bonds repaid by mortgage payments, not State.","kind":"Statute","origin":"a citizens' petition","source":"https://voterguide.sos.ca.gov/propositions/37/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/37/index.htm"},{"designation":"Proposition 38","title":"AUTHORIZES BONDS FOR IMMUNOLOGY MEDICAL RESEARCH. INITIATIVE STATUTE.","text":"Authorizes $8.4 billion in general obligation bonds for immunology and immunotherapy research, half to a single University of California-affiliated nonprofit medical research institute, half to research grants.","kind":"Bond","origin":"a citizens' petition","source":"https://voterguide.sos.ca.gov/propositions/38/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/38/index.htm"},{"designation":"Proposition 39","title":"PROHIBITS CITIZENS FROM VOTING UNLESS THEY PRESENT GOVERNMENT-ISSUED IDENTIFICATION. INITIATIVE CONSTITUTIONAL AMENDMENT.","text":"Invalidates mail ballots that do not have last four digits of designated government-issued identification number written on envelope. Prohibits in-person voting without presenting government-issued identification.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://voterguide.sos.ca.gov/propositions/39/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/39/index.htm"},{"designation":"Proposition 40","title":"IMPOSES ONE-TIME TAX ON CERTAIN TAXPAYERS. INITIATIVE CONSTITUTIONAL AMENDMENT AND STATUTE.","text":"Imposes 5% tax on certain taxpayers with assets over $1 billion; revenue primarily for health care. Exempts revenues from constitutional requirements for school funding and spending limit.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://voterguide.sos.ca.gov/propositions/40/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/40/index.htm"},{"designation":"Proposition 41","title":"PROHIBITS NEW STATE TAXES THAT EXCLUDE REVENUES FROM STATE SPENDING LIMIT. REQUIRES AUDITS FOR NEW STATE SPECIAL TAXES. INITIATIVE CONSTITUTIONAL AMENDMENT.","text":"Nullifies state taxes enacted after January 1, 2026 that exempt their revenues from voter-approved state spending limit. Requires pre-election and recurring audits of programs funded by new special taxes.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://voterguide.sos.ca.gov/propositions/41/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/41/index.htm"},{"designation":"Proposition 42","title":"PROHIBITS NEW STATE PERSONAL PROPERTY TAXES AND CERTAIN RETROACTIVE STATE TAXES. INITIATIVE CONSTITUTIONAL AMENDMENT.","text":"Prohibits any new state tax (1) imposed on the ownership of personal property (all things people own other than real estate), or (2) that applies retroactively based on taxpayer’s past activities. Nullifies taxes enacted after January 1, 2026 that conflict with this measure.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://voterguide.sos.ca.gov/propositions/42/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/42/index.htm"},{"designation":"Proposition 43","title":"LIMITS VOTERS’ ABILITY TO RAISE REVENUES FOR LOCAL GOVERNMENT SERVICES. LEGISLATIVE CONSTITUTIONAL AMENDMENT.","text":"Limits voters’ ability to pass voter-proposed local special taxes by increasing percentage of votes needed to approve such ballot measures from a majority (over 50%) to two-thirds, beginning January 1, 2027.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://voterguide.sos.ca.gov/propositions/43/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/43/index.htm"},{"designation":"Proposition 44","title":"REQUIRES COMMUNITY HEALTH CLINICS SPEND 90% OF REVENUE ON PROGRAM SERVICES. INITIATIVE STATUTE.","text":"Imposes penalties on nonprofit Federally Qualified Health Centers (community clinics providing primary care to medically underserved areas and populations) that spend less than 90% of revenue on “program services” advancing their charitable purpose, including but not limited to patient services.","kind":"Statute","origin":"a citizens' petition","source":"https://voterguide.sos.ca.gov/propositions/44/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/44/index.htm"},{"designation":"Proposition 45","title":"MODIFIES ENVIRONMENTAL REVIEW FOR CERTAIN PROJECTS. INITIATIVE STATUTE.","text":"Amends California Environmental Quality Act (CEQA) to expedite environmental review for certain projects (including most housing, transportation, water, and health projects) by setting deadlines to complete environmental review and resolve lawsuits challenging project approvals.","kind":"Statute","origin":"a citizens' petition","source":"https://voterguide.sos.ca.gov/propositions/45/index.htm","guide":"https://voterguide.sos.ca.gov/propositions/45/index.htm"}],"textNote":"Each proposition's text here is its summary in the Official Voter Information Guide, not the label printed on the ballot."},"CO":{"has":true,"by":"Colorado Secretary of State","read":"2026-10-19","list":{"url":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","title":"Amendments and Propositions on the 2026 Ballot (Colorado Secretary of State)"},"guide":{"url":"https://content.leg.colorado.gov/publications/2026-blue-book","title":"2026 State Ballot Information Booklet (Blue Book), Legislative Council Staff"},"measures":[{"designation":"Amendment 81","title":"Law Enforcement Reporting Requirements to Federal Authorities","text":"Shall there be an amendment to the Colorado Constitution requiring law enforcement to notify the department of homeland security when a person is charged with either a violent crime or any crime if the person has a prior felony conviction if law enforcement cannot determine that the person is lawfully present in the United States?","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=15"},{"designation":"Amendment 82","title":"Right to Natural Gas","text":"Shall there be an amendment to the Colorado Constitution creating new law granting the right for consumers to purchase natural gas for cooking or heating in homes or businesses and for distributors and utilities to sell natural gas to consumers?","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=19"},{"designation":"Amendment 83","title":"Constitutional Right to Hunt and Fish","text":"Shall there be an amendment to the Colorado Constitution creating a constitutional right to hunt, fish, and harvest fish and wildlife by traditional methods, including all species of fish and wildlife managed by the state except non-game species, endangered species, or any species that is illegal to hunt under federal law, and, in connection therewith, establishing hunting and fishing as the preferred means of managing fish and wildlife populations; and preserving the right of the state to regulate hunting, fishing, and wildlife management if necessary for sound scientific wildlife conservation and management, public safety, or to preserve the future of hunting and fishing opportunities for all species?","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=21"},{"designation":"Amendment 84","title":"Mail Ballot Voter Identification","text":"Shall there be an amendment to the Colorado Constitution requiring a voter to sign and include the last four digits of their social security number or their Colorado driver’s license or identification card number on the outside of their mail ballot for any federal or state election, and, in connection therewith, allowing the voter to correct missing or incorrect information, including with alternative forms of identification; and prohibiting a county clerk and recorder from counting the mail ballot unless the problem is fixed?","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=24"},{"designation":"Amendment 85","title":"Plain Language Ballot Questions","text":"Shall there be an amendment to the Colorado Constitution concerning ballot question language, and, in connection therewith, requiring all state and local ballot questions to be written in plain language and at no more than an 8th grade reading level and prohibiting a state statute from requiring language that conflicts with these requirements in ballot questions for citizen-initiated measures?","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=27"},{"designation":"Amendment 86","title":"Congressional Redistricting","text":"Shall there be an amendment to the Colorado Constitution concerning congressional redistricting, and, in connection therewith, reenacting the current process for congressional redistricting in the Colorado Constitution and prohibiting modifications to a final map unless at least three public meetings are held, the modifications do not have the effect of dividing communities of interest or purposefully favoring one political party, and are approved by the congressional redistricting commission and the Colorado Supreme Court?","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=30"},{"designation":"Amendment 87","title":"Graduated Income Tax","text":"SHALL STATE TAXES BE INCREASED $2.7 BILLION ANNUALLY, IN ORDER TO INCREASE OR IMPROVE LEVELS OF PUBLIC SERVICES, INCLUDING K-12 PUBLIC SCHOOL EDUCATION, HEALTH CARE, AND EARLY CHILD CARE AND EDUCATION SERVICES, BY AN AMENDMENT TO THE COLORADO CONSTITUTION AND A CHANGE TO THE COLORADO REVISED STATUTES REPEALING EXISTING LAW AND CREATING NEW LAW TO REPLACE THE UNIFORM STATE INCOME TAX RATE WITH A GRADUATED INCOME TAX STRUCTURE, AND, IN CONNECTION THEREWITH, AMENDING THE TAXPAYER’S BILL OF RIGHTS TO ELIMINATE THE CONSTITUTIONAL REQUIREMENT FOR ALL TAXABLE NET INCOME TO BE TAXED AT ONE RATE WITH NO ADDED TAX ON INCOME; ESTABLISHING VARIOUS INCOME TAX RATES BASED ON THE AMOUNT OF TAXABLE INCOME EARNED BY INDIVIDUALS, ESTATES, TRUSTS, AND CORPORATIONS, WHILE MAINTAINING THE CURRENT 4.4% TAX ON INCOME FROM THE SALE OF A PRINCIPAL RESIDENCE, WHICH WILL RESULT IN THE ESTIMATED CHANGE IN INCOME TAXES OWED BY INDIVIDUALS AS IDENTIFIED IN THE FOLLOWING TABLE; AND AUTHORIZING THE STATE TO RETAIN AND SPEND ANY INCREASED REVENUE FROM THE NEW TAX STRUCTURE, AS A VOTER-APPROVED REVENUE CHANGE, TO SUPPLEMENT CURRENT LEVELS OF FUNDING FOR K-12 PUBLIC SCHOOL EDUCATION, HEALTH CARE, AND EARLY CHILD CARE AND EDUCATION PROGRAMS?\nInitiative 195\nChange in Income Taxes Owed by Income Category\nIncome Categories\tCurrent Average\nIncome Tax Owed\tProposed Average\nIncome Tax Owed\tProposed Change\nin Average Income\nTax Owed if Passed\n+ or -\n$25,000 or less\t$59\t$50\t-$9\n$25,001 - $50,000\t$751\t$632\t-$119\n$50,001 - $100,000\t$1,877\t$1,666\t-$210\n$100,001 - $200,000\t$4,126\t$3,828\t-$298\n$200,001 - $500,000\t$9,344\t$9,019\t-$325\n$500,001 - $1,000,000\t$19,288\t$18,963\t-$325\n$1,000,001 - $2,000,000\t$29,432\t$34,196\t+$4,764\n$2,000,001 - $5,000,000\t$41,196\t$55,110\t+$13,914\nIncome categories use adjusted gross income reported to the federal Internal Revenue Service.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=33"},{"designation":"Proposition NN","title":"State Public K-12 Education Funding","text":"Shall state investment in K-12 public education increase two percent each year for the next ten years, with investments used to increase teacher pay, improve teacher retention, lower class sizes, and increase access to career and technical courses, without raising taxes but instead funded by raising the annual limit on state fiscal year spending only by the amount spent on public K-12 education as a voter-approved revenue change, and requiring an annual publicly released, independent audit to show how the new investments are spent?","kind":"Statute","origin":"the General Assembly","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=41"},{"designation":"Proposition 132","title":"Penalties for Fentanyl Crimes","text":"Shall there be a change to the Colorado Revised Statutes concerning criminal penalties for fentanyl and certain synthetic opioids, and, in connection therewith, increasing the felony classifications of drug-related crimes for distribution, manufacturing, dispensing, sale, or possession of fentanyl and certain synthetic opioids; creating mandated treatment for certain drug felony violations based on possession amount; and changing sentencing provisions to narrow or eliminate exemptions for crimes related to fentanyl and certain synthetic opioids and drug-related deaths?","kind":"Statute","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=48"},{"designation":"Proposition 133","title":"Penalties for Human Trafficking of a Minor","text":"Shall there be a change to the Colorado Revised Statutes modifying existing law concerning human trafficking of a minor for sexual servitude, and, in connection therewith, creating new law expanding human trafficking of a minor for sexual servitude to include knowingly trading anything of monetary value to buy or sell sexual activity with a minor and increasing the penalty to be life in prison without parole or release?","kind":"Statute","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=52"},{"designation":"Proposition 134","title":"Male and Female Participation in School Sports","text":"Shall there be a change to the Colorado Revised Statutes creating new law restricting participation in all K-12 and collegiate school sports based on the participant’s sex as determined by certain aspects of their biological reproductive system, and, in connection therewith, requiring a school, institution of higher education, or athletic association to designate each school or intramural athletic team or sport as male, female, or coeducational; only allowing participants to compete on the team or sport of their designated sex or to compete on a coeducational team; creating an exception to allow a female to participate on a male-designated team or sport if there is no female team available; prohibiting a government entity, licensing or accrediting organization, or athletic association from entertaining a complaint, opening an investigation, or taking other adverse action against a school for maintaining separate teams or sports for females; and providing the commissioner of education with the authority to enforce the proposed initiative for K-12 school districts?","kind":"Statute","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=55"},{"designation":"Proposition 135","title":"Prohibit Certain Surgeries on Minors","text":"Shall there be a change to the Colorado Revised Statutes modifying existing law by prohibiting surgery on a minor for the purpose of altering the minor’s biological sex characteristics, and, in connection therewith, prohibiting any health-care professional or other person from knowingly performing, prescribing, administering, or providing any surgery to a minor for the purpose of altering the minor’s biological sex characteristics and prohibiting the use of state or federal funds, Medicaid reimbursement, or insurance coverage to pay for this type of surgery?","kind":"Statute","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=59"},{"designation":"Proposition 136","title":"Income Tax Rate Cap","text":"Shall there be a change to the Colorado Revised Statutes capping the state income tax rate at 4.4% of federal taxable income for individuals and corporations?","kind":"Statute","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=62"},{"designation":"Proposition 137","title":"Designate Sporting Goods Sales Tax Revenue for Conservation","text":"Shall there be a change to the Colorado Revised Statutes creating new law to increase water and land conservation funding without raising taxes, and, in connection therewith, through a voter-approved revenue change, allowing the state to keep and spend a portion of revenue from the state sales tax on sporting goods and equipment to conserve and protect Colorado’s water, land, and forests, prevent wildfires, support outdoor recreation training and activities, and reduce revenue spent on these conservation purposes if necessary to preserve funding for certain tax credits?","kind":"Statute","origin":"a citizens' petition","source":"https://www.coloradosos.gov/pubs/elections/Initiatives/ballot/contacts/2026.html","guide":"https://content.leg.colorado.gov/sites/default/files/2026-blue-book-en-accessible.pdf#page=64"}]},"CT":{"has":false,"by":"Connecticut Secretary of the State","read":"2026-10-19","list":{"url":"https://portal.ct.gov/sots/election-services/town-ballots/2026-november-town-election-ballots","title":"November 3, 2026 State Election Sample Town Ballots (Connecticut Secretary of the State)"},"none":{"from":"ballots"}},"DC":{"has":true,"by":"D.C. Board of Elections","read":"2026-10-19","list":{"url":"https://www.dcboe.org/elections/2026-elections","title":"2026 Elections, GENERAL ELECTION - November 3, 2026: Sample Ballots (DC Board of Elections)"},"guide":{"url":"https://www.dcboe.org/getContentAsset/5a9ceeda-114c-4171-810d-1317c9e06b0e/5ebbd046-860b-4ee1-81c8-43d0e3bc446e/_-DCBOE-Voter-Guide-Web-Smaller-File.pdf?language=en","title":"District of Columbia Voter Guide, November 3, 2026 Election (DC Board of Elections)"},"measures":[{"designation":"Initiative Measure No. 86","title":"Prohibiting Force-Feeding of Birds Act of 2026","text":"Prohibiting Force-Feeding of Birds Act of 2026.\nIf enacted, this Initiative would:\n(a) Prohibit any person from force-feeding a bird for the purpose of enlarging the bird's liver beyond normal size;\n(b) Ban the sale or distribution of any product resulting from force-feeding a bird, including foie gras;\n(c) Define force-feeding as inserting a tube into the bird's throat to deliver excessive feed;\n(d) Provide for enforcement by the Department of Energy and Environment during routine food safety inspections; and\n(e) Provide for civil penalties.\nYes, to approve\nNo, to reject","kind":"Statute","origin":"a citizens' petition","source":"https://www.dcboe.org/getContentAsset/bf78fba0-50f2-40c4-ad32-0f78255d725a/5ebbd046-860b-4ee1-81c8-43d0e3bc446e/Ward1C.pdf?language=en","guide":"https://www.dcboe.org/getContentAsset/5a9ceeda-114c-4171-810d-1317c9e06b0e/5ebbd046-860b-4ee1-81c8-43d0e3bc446e/_-DCBOE-Voter-Guide-Web-Smaller-File.pdf?language=en#page=20"}]},"DE":{"has":false,"by":"Delaware Department of Elections","read":"2026-10-19","list":{"url":"https://elections.delaware.gov/elections/general/sampleballots/GE2026/index.html","title":"2026 General Election Sample Ballots (Delaware Department of Elections)"},"none":{"from":"ballots"}},"FL":{"has":true,"by":"Florida Division of Elections","read":"2026-10-19","list":{"url":"https://constitutionalinitiatives.dos.fl.gov/","title":"Initiatives / Amendments / Revisions Database (Florida Division of Elections)"},"measures":[{"designation":"Amendment 1","title":"Budget Stabilization Fund","text":"Proposing an amendment to the State Constitution to increase the amount of funds that may be retained in the budget stabilization fund from 10% to 25% of general revenue collections, require the legislature to transfer the lesser of $750 million or the amount required to reach 25% of the general revenue collections each year unless certain conditions are met, and allow the legislature to withdraw funds for critical state needs.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://constitutionalinitiatives.dos.fl.gov/Home/InitDetail?account=10&seqnum=108"},{"designation":"Amendment 2","title":"Exemption of Tangible Personal Property on Agricultural Land from Taxation","text":"Proposing an amendment to the State Constitution to exempt tangible personal property habitually located or typically present on land classified as agricultural, used in the production of agricultural products or for agritourism activities, and owned by the landowner or leaseholder of the agricultural land from ad valorem taxation. If approved this amendment would first apply for tax years beginning January 1, 2027.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://constitutionalinitiatives.dos.fl.gov/Home/InitDetail?account=10&seqnum=109"},{"designation":"Amendment 3","title":"Increased Homestead Exemption; Lower Cap on Increases in Non-Homestead Property Assessments","text":"This amendment increases the homestead exemption, for all non-school taxes, to $150,000 in 2027 and $250,000 in 2028, and adjusts for inflation thereafter. It requires the Legislature to prescribe a uniform procedure for counties and municipalities, for their respective levies, to increase the homestead exemption up to full assessed value, and allows special districts, subject to referendum approval, to do the same. Persons who are not Florida residents on December 31, 2026, will receive the existing homestead exemption upon qualifying for a homestead exemption, with the increased homestead exemption beginning with the fifth year of exemption, to the extent permitted by the U.S. Constitution. This amendment reduces the annual cap on assessment increases for non-homestead properties from 10% to 5%. This amendment requires counties and municipalities to use property taxes solely for public safety, education and schools, infrastructure, natural resources, bond debt service, retirement benefits for employees, and operations and administration. Other expenditures may be approved by county officers or county or municipal governing bodies unless prohibited by general law, notwithstanding Article VII, Section 9(a) of the Florida Constitution, which allows counties and municipalities to levy property taxes for their respective purposes. This amendment takes effect January 1, 2027.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://constitutionalinitiatives.dos.fl.gov/Home/InitDetail?account=10&seqnum=110"}]},"GA":{"has":true,"by":"Georgia Secretary of State","read":"2026-10-19","list":{"url":"https://sos.ga.gov/sites/default/files/2026-09/2026%20Constitutional%20Summaries%20booklet%20FINAL.pdf","title":"Proposed Constitutional Amendments, General Election November 3, 2026: Constitutional Amendments 1-3 and Summaries of Amendments (Georgia Secretary of State)"},"guide":{"url":"https://sos.ga.gov/page/proposed-georgia-constitution-amendments","title":"Proposed Georgia Constitution Amendments (Georgia Secretary of State)"},"measures":[{"designation":"Amendment 1","title":"Increases the maximum qualifying acreage for assessment and taxation as bona fide conservation use property.","text":"Shall the Constitution of Georgia, for the purpose of protecting family farmland, be amended so as to increase the maximum acreage to qualify for assessment and taxation as a bona fide conservation use property from 2,000 acres to 4,000 acres?","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://sos.ga.gov/sites/default/files/2026-09/2026%20Constitutional%20Summaries%20booklet%20FINAL.pdf","guide":"https://sos.ga.gov/sites/default/files/2026-09/2026%20Constitutional%20Summaries%20booklet%20FINAL.pdf"},{"designation":"Amendment 2","title":"Provides for the nonpartisan election of all probate court judges.","text":"Shall the Constitution of Georgia be amended so as to require that all probate court judges be elected in nonpartisan elections?","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://sos.ga.gov/sites/default/files/2026-09/2026%20Constitutional%20Summaries%20booklet%20FINAL.pdf","guide":"https://sos.ga.gov/sites/default/files/2026-09/2026%20Constitutional%20Summaries%20booklet%20FINAL.pdf"},{"designation":"Amendment 3","title":"Authorizes creation of Georgia Next Generation 9-1-1 Fund for 9-1-1 systems expansion, maintenance, and operation.","text":"Shall the Constitution of Georgia be amended so as to authorize the General Assembly to dedicate certain existing revenues, including revenues reallocated by law, to a nonlapsing fund to be used exclusively for the expansion, maintenance, and operation of emergency 9-1-1 systems in this state?","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://sos.ga.gov/sites/default/files/2026-09/2026%20Constitutional%20Summaries%20booklet%20FINAL.pdf","guide":"https://sos.ga.gov/sites/default/files/2026-09/2026%20Constitutional%20Summaries%20booklet%20FINAL.pdf"}]},"GU":{"has":false,"by":"Guam Election Commission","read":"2026-10-19","list":{"url":"https://drive.google.com/file/d/1RKr3bLuivj8n0n29XKbQVHEgdUYwILMN/view","title":"Sample General Election Ballot, November 3, 2026 (Guam Election Commission)"},"none":{"from":"ballots"}},"HI":{"has":true,"by":"Hawaii Office of Elections","read":"2026-10-19","list":{"url":"https://elections.hawaii.gov/voting/2026-proposed-amendments-to-the-hawaii-state-constitution/","title":"2026 Proposed Amendments to the Hawaii State Constitution (State of Hawaii Office of Elections)"},"guide":{"url":"https://elections.hawaii.gov/wp-content/uploads/VoterGuide_2026_General_English.pdf","title":"2026 Voter Guide, General Election (State of Hawaii Office of Elections)"},"measures":[{"designation":"Question #1","title":"Increasing the Timeframe for the Hawaii Senate to Consider and Act on Judicial Appointments.","text":"Shall the Constitution of the State of Hawaii be amended to allow the Senate more time to consider and act on the appointments of justices and judges, by increasing the timeframe from thirty days to sixty days for appointments made between April 1 and December 31 when the senate is not in regular session or is about to adjourn the regular session?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://elections.hawaii.gov/voting/2026-proposed-amendments-to-the-hawaii-state-constitution/","guide":"https://elections.hawaii.gov/wp-content/uploads/VoterGuide_2026_General_English.pdf"},{"designation":"Question #2","title":"Directing the Hawaii State Legislature to Establish Procedures for Counties to Issue RISE Bonds, Exempt from County Debt Limits.","text":"Shall the Hawaii State Constitution be amended to direct the legislature to authorize the counties to issue resilient infrastructure for shelter and equity bonds to fund public improvements in designated districts, repaid solely by future growth in property tax revenues within those districts, not by increasing real property tax rates, where such bonds are excluded from the counties' debt limit and are subject to accountability and oversight requirements as may be provided by law?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://elections.hawaii.gov/voting/2026-proposed-amendments-to-the-hawaii-state-constitution/","guide":"https://elections.hawaii.gov/wp-content/uploads/VoterGuide_2026_General_English.pdf"}]},"IA":{"has":true,"by":"Iowa Secretary of State","read":"2026-10-19","list":{"url":"https://www.legis.iowa.gov/docs/aco/bulletincontent/06-24-2026.Regulatory%20Analysis_1780517797265.pdf","title":"Secretary of State, Regulatory Analysis RA 26-93 (Iowa Administrative Bulletin, June 24, 2026)"},"measures":[{"designation":"Constitutional Amendment 1","title":"Proposed Constitutional Amendment -- Certain Tax Law Changes -- Two-Thirds Majority Vote Required (S.J.R. 11; Acts 2026, ch. 1201)","text":"Shall the following amendment to the Constitution be adopted? Summary: Provides that any bill to increase the individual income tax rate or the corporate income tax rate, or the rate of any other type of tax based upon income or legal and special reserves, shall require the affirmative votes of at least two-thirds of the members elected to each house of the legislature for passage. Further, the two-thirds majority vote requirement applies to the passage of a bill to establish a new tax on any type of income or legal and special reserves imposed by the state. The requirement excludes taxes imposed at the option of a local government. A lawsuit challenging the proper enactment of a bill under this section must be filed no later than one year following the enactment. Full Text: The Constitution of the State of Iowa is amended by adding the following new section to new Article XIII: Passage of a bill that increases the individual income tax rate or the corporate income tax rate, or the rate of any other type of tax based upon income or legal and special reserves, shall require the affirmative votes of at least two-thirds of the members elected to each house of the general assembly. This requirement does not apply to taxes imposed at the option of a local government. Passage of a bill that establishes a new tax on any type of income or legal and special reserves imposed by the state shall require the affirmative votes of at least two-thirds of the members elected to each house of the general assembly. A lawsuit challenging the proper enactment of a bill under this section must be filed no later than one year following the enactment. If such a lawsuit is not filed within the one-year limit, the bill shall be considered properly enacted under this section. Each bill to which this section applies must include a separate provision describing the requirements for enactment prescribed by this section. The general assembly shall enact laws to implement this section.","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.legis.iowa.gov/docs/aco/bulletincontent/06-24-2026.Regulatory%20Analysis_1780517797265.pdf"}]},"ID":{"has":true,"by":"Idaho Secretary of State","read":"2026-10-19","list":{"url":"https://voteidaho.gov/idaho-general-election/","title":"2026 Idaho General Election (VoteIdaho.gov, Idaho Secretary of State)"},"guide":{"url":"https://archive.voteidaho.gov/download/2026_Voter_Pamphlet.pdf","title":"Idaho Voter Pamphlet, General Election, November 3, 2026 (Idaho Secretary of State)"},"measures":[{"designation":"House Joint Resolution 4","title":"A Joint Resolution proposing an Amendment to Section 26, Article III of the Constitution of the State of Idaho relating to psychoactive substances","text":"Shall Section 26, Article III of the Constitution of the State of Idaho be amended to provide that only the Idaho Legislature shall have power and authority to legalize the growing, producing, manufacturing, transporting, selling, delivering, dispensing, administering, prescribing, distributing, possessing, or using of marijuana, narcotics, or other psychoactive substances?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://voteidaho.gov/idaho-general-election/","guide":"https://voteidaho.gov/idaho-general-election/"},{"designation":"House Joint Resolution 6","title":"A Joint Resolution proposing an Amendment to Article X of the Constitution of the State of Idaho, by the addition of a new Section 8, Article X, relating to English as the official language of the state of Idaho","text":"Shall Article X of the Constitution of the State of Idaho be amended by the addition of a new Section 8, to provide that the English language shall be the official language for the state of Idaho, and to further provide that, except as required by federal law, English shall be used in all public proceedings, public documents, public instruction, and any other public acts of any public institution in the state of Idaho?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://voteidaho.gov/idaho-general-election/","guide":"https://voteidaho.gov/idaho-general-election/"},{"designation":"Proposition One","title":"Measure creating right to abortion before fetus viability, and post-viability to protect health; right to privacy; healthcare provider liability protections.","text":"The measure seeks to change Idaho's laws by introducing a right to reproductive freedom and privacy including a right to abortion up to the point of the fetus's ability to survive outside the womb. After fetal viability, there would be no general right to abortion except in cases of \"medical emergency.\" The \"medical emergency\" exception would expand Idaho's current life exception and allow abortions when pregnant women face complicating physical conditions that threaten their life or health, \"including serious impairment to a bodily function\" or \"serious dysfunction of any bodily organ or part.\" The proposed measure codifies a right to make reproductive decisions, including contraception, fertility treatment, and prenatal and postpartum care. This includes a \"right of privacy\" in making these decisions. The measure seeks to prevent the state from enforcing certain abortion laws protecting the life of the unborn child. It would also impose a requirement that any restrictions on reproductive decisions, including abortion prior to fetus viability, must be \"narrowly tailored to improve or maintain the health of the person seeking reproductive health care.\" The measure would also prevent the state from penalizing patients, healthcare providers, or anyone who assists in exercising the proposed right.","kind":"Statute","origin":"a citizens' petition","source":"https://voteidaho.gov/initiatives-amendments/","guide":"https://voteidaho.gov/idaho-general-election/"},{"designation":"Advisory Question - House Bill 932","title":"Advisory Question: State Gun","text":"Which of the following guns should be designated as the state gun of Idaho? Please choose only one answer. (a) Winchester Model 1894 (.30-30); (b) Winchester Model 1873 \"Gun that Won the West\" (.44-40); (c) 1873 Colt Single Action Army Revolver \"Peacemaker\" (.45 Colt); (d) M1 Garand rifle (.30-06); (e) Colt M1911 .45 automatic Colt pistol (.45 ACP); or (f) Remington Model 700 bolt-action rifle (.30-06)","kind":"Advisory question","origin":"the Legislature","source":"https://archive.voteidaho.gov/download/2026_Voter_Pamphlet.pdf","guide":"https://voteidaho.gov/idaho-general-election/"}]},"IL":{"has":false,"by":"Illinois State Board of Elections","read":"2026-10-19","list":{"url":"https://votersguide.elections.il.gov/Questions.aspx","title":"Illinois Voters' Guide - 2026 - GENERAL ELECTION: Questions of Public Policy (Illinois State Board of Elections)"},"guide":{"url":"https://votersguide.elections.il.gov/","title":"Illinois Voters' Guide (Illinois State Board of Elections)"},"none":{"from":"statement","words":"There are no statewide questions of public policy for this election."}},"IN":{"has":true,"by":"Indiana Election Division","read":"2026-10-19","list":{"url":"https://www.in.gov/sos/elections/files/Dispatch.Aug-2026.FINAL.pdf","title":"Indiana Election Division Dispatch, August 2026 (Indiana Election Division)"},"measures":[{"designation":"Public Question #1","title":"Limitations on the Right to Bail","text":"Currently, under the Constitution of the State of Indiana, a person charged with murder or treason is not entitled to be released on bail if the proof is evident or the presumption strong. Shall the Constitution of the State of Indiana be amended to provide that a person charged with an offense other than murder or treason is not entitled to bail if: (1) the proof is evident or the presumption strong; and (2) the state proves by clear and convincing evidence that no release conditions will reasonably protect the safety of any other person or the community. (This question concerns Article 1, Section 17 of the Constitution of the State of Indiana.)","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.in.gov/dA/d13ecb1f55/2026-Indiana-Election-Legislation-Summary.FINAL.pdf?language_id=1"},{"designation":"Public Question #2","title":"Residence for Town and City Court Judges","text":"Shall the Constitution of the State of Indiana be amended to permit the judge of a city or town court to reside in: (1) the county in which the court is located; or (2) the bordering county closest to the city or town in which the court is located? (This question concerns Article 6, Section 6 of the Constitution of the State of Indiana.)","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.in.gov/dA/d13ecb1f55/2026-Indiana-Election-Legislation-Summary.FINAL.pdf?language_id=1"}]},"KS":{"has":true,"by":"Kansas Secretary of State","read":"2026-10-19","list":{"url":"https://sos.ks.gov/elections/proposed-constitutional-amendments.html","title":"Proposed Constitutional Amendments (Kansas Secretary of State)"},"measures":[{"designation":"Constitutional Amendment","title":"Qualifications of electors","text":"Explanatory statement. This amendment would clarify that only a person who is a citizen of the United States is eligible to vote in this state. A vote for this proposition would clarify that only a person who is a citizen of the United States is eligible to vote in this state. A vote against this proposition would make no change to the constitution of the state of Kansas, and the language concerning voter qualifications would remain the same. Shall the following be adopted? ...","kind":"Constitutional amendment","origin":"the Legislature","source":"https://sos.ks.gov/elections/26elec/2026-General-Election-Constitutional-Amendment-Citizen-Clarification.pdf","cut":true,"guide":"https://sos.ks.gov/elections/proposed-constitutional-amendments.html"}]},"KY":{"has":true,"by":"Kentucky Secretary of State","read":"2026-10-19","list":{"url":"https://sos.ky.gov/elections/Pages/Constitutional-Amendments.aspx","title":"2026 Constitutional Amendments (Kentucky Secretary of State)"},"guide":{"url":"https://sos.ky.gov/elections/Pages/Constitutional-Amendments.aspx","title":"2026 Constitutional Amendments (Kentucky Secretary of State)"},"measures":[{"designation":"Constitutional Amendment 1","title":null,"text":"Are you in favor of limiting a Governor's ability to grant pardons or commute sentences by prohibiting him or her from granting pardons or commuting sentences during the time period beginning 60 days prior to the general election at which the Governor is elected, and ending when the Governor is sworn in for that term by amending the Constitution of Kentucky as stated below? It is proposed that Section 77 of the Constitution of Kentucky be amended to read as follows: ...","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://sos.ky.gov/elections/Pages/Constitutional-Amendments.aspx","cut":true,"guide":"https://sos.ky.gov/elections/Pages/Constitutional-Amendments.aspx"}]},"LA":{"has":true,"by":"Louisiana Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","title":"2026 Proposed Constitutional Amendments, November 3, 2026 Election (Louisiana Secretary of State)"},"guide":{"url":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf","title":"Statements of Proposed Constitutional Amendments, November 3, 2026 (Louisiana Secretary of State)"},"measures":[{"designation":"Proposed Amendment No. 1","title":"Allows a one-time transfer of a property tax exemption for the surviving spouse of a disabled veteran","text":"Do you support an amendment to allow the surviving spouse of a deceased veteran with a service-connected disability, who receives the additional property tax exemption, to make a one-time transfer of the additional property tax exemption to a subsequent qualifying property? (Effective January 1, 2027) (Amends Article VII, Section 21(K)(1))","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","guide":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf"},{"designation":"Proposed Amendment No. 2","title":"Authorizes a local taxing authority to levy a lower millage rate without losing its ability to adjust to the prior year's maximum authorized millage rate","text":"Do you support an amendment to allow a local taxing authority to continue to levy a lower millage rate without losing its ability to adjust to the maximum authorized millage rate from a prior year's reassessment? (Effective January 1, 2027) (Amends Article VII, Section 23(C))","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","guide":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf"},{"designation":"Proposed Amendment No. 3","title":"Prohibits post-conviction bail for a defendant who is convicted of an aggravated offense against a victim who is a minor","text":"Do you support an amendment to prohibit a defendant from being released on any post-conviction bail if the defendant is convicted of an aggravated offense against a minor child? (Adds Article I, Section 18(C))","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","guide":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf"},{"designation":"Proposed Amendment No. 4","title":"Places a lifetime term limit on a person who has served as governor for more than one and one-half terms","text":"Do you support an amendment to prohibit a person who has served more than one and one-half terms as governor from being elected as governor for any future term? (Amends Article IV, Section 3(B))","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","guide":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf"},{"designation":"Proposed Amendment No. 5","title":"Authorizes a state retirement system receiving nonrecurring state monies to apply those monies to any of its outstanding unfunded accrued liability (UAL) rather than its oldest UAL first","text":"Do you support an amendment to authorize a state retirement system to apply any nonrecurring state monies it receives to any of its unfunded accrued liability rather than requiring application to its oldest unfunded accrued liability? (Amends Article VII, Section 10(D)(2)(b)(iii))","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","guide":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf"},{"designation":"Proposed Amendment No. 6","title":"Authorizes extension of an additional property tax exemption for owners who are 65 or older","text":"Do you support an amendment to authorize parishes and municipalities to extend an additional property tax exemption for property subject to the homestead exemption that is owned and occupied by a person who is at least sixty-five years of age and who qualifies for the special assessment level? (Effective January 1, 2028) (Adds Article VII, Section 21(P))","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","guide":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf"},{"designation":"Proposed Amendment No. 7","title":"Authorizes the use of public funds to identify, inventory, remove, or replace certain water lines on property owned by utility customers","text":"Do you support an amendment to allow for the use of public funds by a political subdivision for the purpose of identifying, inventorying, removing or replacing drinking water utility service lines made of or affected by materials as specified or prescribed by the Lead and Copper Rule Improvements of the United States Environmental Protection Agency, promulgated October 30, 2024, or subsequent promulgation, on property owned by utility customers? (Amends Article VII, Section 14)","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","guide":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf"},{"designation":"Proposed Amendment No. 8","title":"Prohibits expropriation of property by a foreign adversary or an agent of a foreign adversary","text":"Do you support an amendment to prohibit expropriation of property by a foreign adversary or an agent of a foreign adversary? (Amends Article I, Section 4(B)(4))","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","guide":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf"},{"designation":"Proposed Amendment No. 9","title":"Increases the income limit for qualifying for the special property tax assessment level from $100,000, to be adjusted annually for inflation beginning in 2026, to $150,000, to be adjusted annually for inflation beginning in 2028","text":"Do you support an amendment to increase the maximum amount of income a person may receive and still qualify for the special assessment level for residential property receiving the homestead exemption? (Effective January 1, 2027) (Amends Article VII, Section 18(G)(1)(a)(ii))","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","guide":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf"},{"designation":"Proposed Amendment No. 10","title":"Authorizes an exemption from property taxes for blighted or derelict property that has been rehabilitated and requires the legislature to enact laws relative to implementation and administration of the exemption","text":"Do you support an amendment to allow property tax exemptions for blighted or derelict properties that have been rehabilitated, and to require the legislature to enact laws providing for administration of these exemptions? (Effective January 1, 2027) (Adds Article VII, Section 21(P))","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.la.gov/media/jo2die1s/proposed-constitutional-amendments-2026-nov.pdf","guide":"https://www.sos.la.gov/media/j2fjvpye/proposed-constitutional-amendments-2026-nov-summaries.pdf"}]},"MA":{"has":true,"by":"Secretary of the Commonwealth of Massachusetts","read":"2026-10-19","list":{"url":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-questions.htm","title":"Massachusetts Information for Voters 2026 Ballot Questions - About the 2026 Ballot Questions (Secretary of the Commonwealth)"},"guide":{"url":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/main.htm","title":"Massachusetts Information for Voters: 2026 Ballot Questions (Secretary of the Commonwealth)"},"measures":[{"designation":"Question 1","title":"Expanding the Public Records Law","text":"Do you approve of a law summarized below, on which no vote was taken by the Senate or the House of Representatives before May 6, 2026? This proposed law would make most records held by the Legislature and the Office of the Governor public records under the Massachusetts Public Records Law. This proposed law would exempt documents related to the development of public policy and communications between legislators and their constituents, if those communications are reasonably related to a constituent's request for assistance in obtaining government-provided benefits or services or interacting with a government agency.","kind":"Statute","origin":"a citizens' petition","source":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question1.htm","guide":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question1.htm"},{"designation":"Question 2","title":"Collective Bargaining for CPCS Employees","text":"Do you approve of a law summarized below, on which no vote was taken by the Senate or the House of Representatives before May 6, 2026? This proposed law would specify that employees of the Committee for Public Counsel Services (\"CPCS\") are permitted to engage in collective bargaining with their employer. It would also require CPCS, after executing a collective bargaining agreement, to request the appropriation necessary to fund such agreement from the Governor.","kind":"Statute","origin":"a citizens' petition","source":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question2.htm","guide":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question2.htm"},{"designation":"Question 3","title":"State Primary Elections","text":"Do you approve of a law summarized below, on which no vote was taken by the Senate or the House of Representatives before May 6, 2026? This proposed law would eliminate political party primaries for state elections and instead establish a system where there would be a single, all-party primary in which all candidates, regardless of their party affiliation, would be listed on one ballot, and voters could vote for any candidate on the ballot. The two candidates receiving the most votes in the primary would advance to the general election ballot. This proposed law would require candidates for governor and lieutenant governor to run and be listed jointly on the ballot in the primary. This proposed law would provide political party status to any group whose candidates for any statewide office received at least 3% of the ballots cast in the state primary.","kind":"Statute","origin":"a citizens' petition","source":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question3.htm","guide":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question3.htm"},{"designation":"Question 4","title":"Election Day Registration","text":"Do you approve of a law summarized below, on which no vote was taken by the Senate or the House of Representatives before May 6, 2026? This proposed law would permit eligible individuals to register to vote or update their voter registration address on Election Day. ...","kind":"Statute","origin":"a citizens' petition","source":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question4.htm","cut":true,"guide":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question4.htm"},{"designation":"Question 5","title":"State Revenue Limit & Rebate","text":"Do you approve of a law summarized below, on which no vote was taken by the Senate or the House of Representatives before May 6, 2026? This proposed law would change the limit on how much revenue the state can collect in a given year. The proposal would limit state revenue in a given year to the net amount of state revenue from the year before, increased by a rate equal to the average growth of wages and salaries in Massachusetts over the most recent three years. If revenue collected by the state in a given year exceeds the limit, the excess amount would be refunded to taxpayers the following year. The proposed law would include all revenue from the surtax on incomes over $1 million when calculating the revenue limit and when determining whether state revenue exceeds the limit. The provisions of the proposed law would all be effective as of July 1, 2027. The proposed law states that, if any of its parts were declared invalid, the other parts would stay in effect.","kind":"Statute","origin":"a citizens' petition","source":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question5.htm","guide":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question5.htm"},{"designation":"Question 6","title":"Natural Resource Conservation Fund","text":"Do you approve of a law summarized below, on which no vote was taken by the Senate or the House of Representatives before May 6, 2026? This proposed law would establish a Nature for All Fund that, subject to appropriation by the Legislature, would receive 50% of state taxes collected from the sale and use of sporting goods, recreational vehicles, and golf courses for the first year of its operation. After July 1, 2028, the Nature for All Fund would begin receiving, subject to appropriation by the Legislature, 100% of state taxes collected on the sale and use of sporting goods, recreational vehicles, and golf courses. The sales tax revenue received by the Nature for All Fund would exclude sales tax revenue transferred to the Massachusetts Bay Transportation Authority State and Local Contribution Fund and the School Modernization and Reconstruction Trust Fund. The proposed law would allow the state Executive Office of Energy and Environmental Affairs to spend the money in the Nature for All Fund for natural resource conservation. ...","kind":"Statute","origin":"a citizens' petition","source":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question6.htm","cut":true,"guide":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question6.htm"},{"designation":"Question 7","title":"Single Family Homes","text":"Do you approve of a law summarized below, on which no vote was taken by the Senate or the House of Representatives before May 6, 2026? This proposed law would allow single-family homes to be built in a residentially zoned area as long as the land on which it is to be constructed is at least 5,000 square feet, has at least 50 feet of land bordering the street, road, or public way that it faces, and has access to public sewer and water services. The proposed law would allow cities and towns to reasonably regulate certain aspects of those single-family homes, including their height, distance from neighboring buildings, open space, parking requirements, and whether they can be rented out on a short-term basis. The proposed law would also allow the Executive Office of Housing and Livable Communities to issue guidance or regulations to administer the proposed law.","kind":"Statute","origin":"a citizens' petition","source":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question7.htm","guide":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question7.htm"},{"designation":"Question 8","title":"Prohibit Retail Sale of Adult Recreational Use Marijuana","text":"Do you approve of a law summarized below, on which no vote was taken by the Senate or the House of Representatives before May 6, 2026? The proposed law would change the type and amount of marijuana that may legally be possessed in Massachusetts by repealing the laws that legalize, regulate, and tax the retail sale of adult recreational use marijuana in Massachusetts. The proposed law would also permit persons 21 years of age and older to possess 1 ounce or less of marijuana including no more than 5 grams in the form of concentrate, and to gift or transfer to another person 21 years of age and older 1 ounce or less of marijuana including no more than 5 grams in the form of concentrate. The proposed law would also impose a civil penalty of $100 and forfeiture of the marijuana for the possession of marijuana between the weight of 1 and 2 ounces. ...","kind":"Statute","origin":"a citizens' petition","source":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question8.htm","cut":true,"guide":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question8.htm"},{"designation":"Question 9","title":"Firearms Regulation","text":"Do you approve of a law summarized below, which was approved by the House of Representatives on July 18, 2024 by a vote of 124 to 33, and approved by the Senate on July 18, 2024 by a vote of 35 to 5? This law makes a number of changes to Massachusetts laws governing firearms. The law adds school administrators and licensed healthcare providers as parties permitted to ask a court to issue an Extreme Risk Protection Order – requiring an individual to surrender or relinquish their firearm licenses, permits, and firearms - if an individual is a present danger to self or others. The law also provides that, when issuing a Harassment Prevention Order, a court may also order the surrender of firearms licenses, permits, and firearms. ...","kind":"Referendum on a law","origin":"a citizens' petition","source":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question9.htm","cut":true,"guide":"https://www.sec.state.ma.us/divisions/elections/research-and-statistics/2026-Information-for-voters/2026-ballot-question9.htm"}]},"MD":{"has":true,"by":"Maryland State Board of Elections","read":"2026-10-19","list":{"url":"https://elections.maryland.gov/elections/2026/ballot_questions.html","title":"Ballot Questions for the November 3, 2026 Election (Maryland State Board of Elections)"},"guide":{"url":"https://elections.maryland.gov/elections/2026/ballot_questions.html","title":"Ballot Questions for the November 3, 2026 Election (Maryland State Board of Elections)"},"measures":[{"designation":"Question 1","title":"Arbitration Reform for State Employees Act of 2026","text":"Providing that each budget submitted by the Governor shall include proposed expenditures necessary to implement wages, hours, fringe benefits, health benefits, and other terms and conditions of employment in each collective bargaining memorandum of understanding with State employees, whether the State and State employees reached those terms and conditions by mutual agreement or through a neutral decider's order. A vote FOR this amendment means that the Governor has to include money in the proposed State budget to pay for agreements between the State and its employees. Agreements might include changes to wages, hours, fringe benefits, health benefits, and other terms and conditions of employment. The Governor must put enough money in the State budget to cover the agreed upon pay and benefits for employees, whether those terms were negotiated or decided by a neutral decision-maker. A vote AGAINST the amendment means that the law about funding agreements between the State and State employees stays the same. (Amending Article III of the Maryland Constitution)","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://elections.maryland.gov/elections/2026/general_ballots/Allegany.pdf","guide":"https://elections.maryland.gov/elections/2026/ballot_questions.html"},{"designation":"Question 2","title":"Temporary Appointments on the Commission on Judicial Disabilities","text":"Authorizing temporary substitute appointments to the Commission on Judicial Disabilities when a member is recused or disqualified, or when a member's term expires. In these situations, the Commission Chair may recall a former member of the Commission, or the Governor, at the request of the Commission Chair, may appoint a temporary substitute member or extend the term of a current member until a permanent replacement is appointed. Only individuals who meet the constitutional eligibility requirements may be recalled or appointed to the Commission. A vote FOR this amendment means that temporary appointments to the Commission are allowed if a member is recused, disqualified, or if a member's term ends without a replacement. The Commission Chair can temporarily fill an opening on the Commission with a former member. The Governor can, at the request of the Commission Chair, pick a temporary substitute to fill an opening on the Commission or extend the term of a current member until a replacement is appointed. Only individuals who meet the constitutional eligibility requirements may be recalled or appointed to the Commission. A vote AGAINST the amendment means that current membership rules for the Commission stay the same. Temporary appointments are not allowed if a member is recused, disqualified, or if a member's term ends. (Amending Article IV of the Maryland Constitution)","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://elections.maryland.gov/elections/2026/general_ballots/Allegany.pdf","guide":"https://elections.maryland.gov/elections/2026/ballot_questions.html"},{"designation":"Question 3","title":"Election Districts – General Assembly and Representatives in Congress","text":"FOR the purpose of clarifying that certain requirements apply only to districts for the election of members of the Senate of Maryland and the House of Delegates; authorizing the General Assembly to grant original jurisdiction to the Supreme Court of Maryland to review the congressional districting plan of the State; and providing that nothing in the Maryland Constitution provides applicable criteria for the boundaries of a congressional districting plan. (Amending Article III of the Maryland Constitution)","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://elections.maryland.gov/elections/2026/ballot_questions.html","guide":"https://elections.maryland.gov/elections/2026/ballot_questions.html"}]},"ME":{"has":null,"by":"Maine Secretary of State","read":"2026-10-19","office":{"url":"https://www.maine.gov/sos/elections-voting/upcoming-elections","name":"Maine Secretary of State, Upcoming Elections"}},"MI":{"has":true,"by":"Michigan Bureau of Elections","read":"2026-10-19","list":{"url":"https://www.michigan.gov/sos/-/media/Project/Websites/sos/Elections/Home/Documents/2026-November-ballot-questions.pdf","title":"2026 November ballot questions (Michigan Bureau of Elections)"},"measures":[{"designation":"Proposal 2026-1","title":"A proposal to convene a constitutional convention for the purpose of drafting a general revision of the state constitution","text":"Shall a convention of elected delegates be convened in 2027 to draft a general revision of the State Constitution for presentation to the state’s voters for their approval or rejection?","kind":"Constitutional convention question","origin":"the Michigan Constitution, which asks this question every 16 years (Article XII, Section 3)","source":"https://www.michigan.gov/sos/-/media/Project/Websites/sos/Elections/Home/Documents/2026-November-ballot-questions.pdf"},{"designation":"Proposal 2026-2","title":"A proposed initiated law to prohibit campaign contributions from certain regulated utilities and government contractors and apply campaign finance laws and regulations to additional types of political communications","text":"The proposal would: • Prohibit regulated electric and gas utilities, contractors with over $250,000 annually in government contracts, and people and organizations with substantial connections to these utilities/contractors from making direct or indirect campaign contributions to those who run for or hold offices that impact them. • Expand laws regulating spending on political communications, including those requiring disclosing donor information, to apply to communications clearly identifying candidates or ballot questions, even if they do not expressly advocate voting for/against them. • Expressly apply the law requiring disclosure of who paid for political communications to internet political communications. Should this proposal be adopted?","kind":"Statute","origin":"a citizens' petition","source":"https://www.michigan.gov/sos/-/media/Project/Websites/sos/Elections/Home/Documents/2026-November-ballot-questions.pdf"}]},"MN":{"has":true,"by":"Minnesota Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.mn.gov/elections-voting/whats-on-my-ballot/constitutional-amendments/","title":"Constitutional amendments (Minnesota Secretary of State)"},"guide":{"url":"https://www.sos.mn.gov/elections-voting/whats-on-my-ballot/constitutional-amendments/","title":"Constitutional amendments (Minnesota Secretary of State)"},"measures":[{"designation":"Constitutional Amendment","title":"Increasing funding to school districts","text":"Shall the Minnesota Constitution be amended to increase the funding going to all school districts from the permanent school fund, which is a fund that supports school districts without raising individual income or property taxes, effective July 1, 2027?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.mn.gov/elections-voting/whats-on-my-ballot/constitutional-amendments/","guide":"https://www.sos.mn.gov/elections-voting/whats-on-my-ballot/constitutional-amendments/"}]},"MO":{"has":true,"by":"Missouri Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures","title":"2026 Ballot Measures (Missouri Secretary of State)"},"guide":{"url":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures","title":"2026 Ballot Measures (Missouri Secretary of State): official ballot titles and fair ballot language"},"measures":[{"designation":"Amendment 3","title":null,"text":"Shall the Missouri Constitution be amended to: Repeal the 2024 voter-approved Amendment providing reproductive healthcare rights, including abortion through fetal viability; Allow abortions for rape and incest (under twelve-weeks’ gestation), emergencies, and fetal anomalies; Allow legislation regulating abortion; Ensure parental consent for minors’ abortions; Prohibit gender transition procedures for minors? State governmental entities estimate no costs or savings. Greene County estimates it may experience an unknown increase in tax revenue. Other local governmental entities estimate no costs or savings.","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures","guide":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures"},{"designation":"Amendment 6","title":null,"text":"Shall the Missouri Constitution be amended to: expand the initiative and referendum petition process by making it a fundamental right; allow courts to revise ballot summaries through lawsuits; prohibit the legislature from weakening initiative or referendum powers; prohibit the legislature from changing or repealing laws enacted through the initiative process, or passing laws similar to those rejected by referendum, without approval from at least 80% of both chambers; and preserve existing majority vote and signature requirements for initiative and referendum petitions? State and local governmental entities estimate no costs or savings.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures","guide":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures"},{"designation":"Amendment 7","title":null,"text":"Shall the Missouri Constitution be amended to establish a permanent public endowment fund to support state government instead of taxing Missouri residents, prohibit the General Assembly from appropriating or diverting the fund, and eliminate state-imposed taxes once the fund generates sufficient revenue to replace them? State and local governmental entities estimate no costs or savings.","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures","guide":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures"},{"designation":"Amendment 8","title":null,"text":"Shall the Missouri Constitution be amended to support law enforcement by preserving the right of citizens to elect a county sheriff, prohibiting the removal of a county sheriff except by a writ of quo warranto, and recognizing the office of sheriff as part of the administration of justice? State and local governmental entities estimate no costs or savings.","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures","guide":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures"},{"designation":"Proposition A","title":null,"text":"Do the people of the state of Missouri approve the act of the General Assembly entitled “House Bill No. 1 (2025 Second Extraordinary Session),” which repeals Missouri’s existing congressional plan, and replaces it with new congressional boundaries that keep more counties intact? State and local governmental entities estimate no costs or savings.","kind":"Referendum on a law","origin":"a citizens' petition","source":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures","guide":"https://www.sos.mo.gov/elections/petitions/2026BallotMeasures"}]},"MP":{"has":true,"by":"Commonwealth Election Commission","read":"2026-10-19","list":{"url":"https://www.votecnmi.gov.mp/downloads/2026/2026_GE_BALLOT_SPECIMEN.pdf","title":"2026 General Election ballot specimen (Commonwealth Election Commission)"},"measures":[{"designation":"Constitutional Convention","title":"CONSTITUTIONAL CONVENTION","text":"Shall there be a constitutional convention to propose amendments to the Constitution?","kind":"Constitutional convention question","origin":null,"source":"https://www.votecnmi.gov.mp/downloads/2026/2026_GE_BALLOT_SPECIMEN.pdf"}]},"MS":{"has":false,"by":"Mississippi Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.ms.gov/content/documents/Elections/2026/Sample%20Ballot%209-9-26.pdf","title":"SAMPLE Official Election Ballot, State of Mississippi, Federal and Judicial Election, Tuesday, November 3, 2026 (Secretary of State)"},"none":{"from":"ballots"}},"MT":{"has":true,"by":"Montana Secretary of State","read":"2026-10-19","list":{"url":"https://sosmt.gov/elections/ballot_issues/proposed-2026-ballot-issues/","title":"Proposed 2026 Ballot Issues - Official Montana Secretary of State Website"},"guide":{"url":"https://sosmt.gov/elections/vip/","title":"2026 Montana Voter Information Pamphlet (Secretary of State)"},"measures":[{"designation":"CI-132","title":"Constitutional Initiative No. 132: A Constitutional Amendment Proposed by Initiative Petition","text":"CI-132 amends the Montana Constitution to require that judicial elections remain nonpartisan.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://sosmt.gov/wp-admin/admin-ajax.php?juwpfisadmin=false&action=wpfd&task=file.download&wpfd_category_id=35&wpfd_file_id=77619&token=c4ef8b9f51434e00a7a58950f02fec1f&preview=1","guide":"https://sosmt.gov/elections/vip/"},{"designation":"CI-133","title":"Constitutional Initiative No. 133: A Constitutional Amendment Proposed by Initiative Petition","text":"The Montana constitution reserves to the people the powers of initiative and referendum. CI-133 amends the constitution to secure this fundamental right from interference by the government. Specifically, CI-133 requires impartial, predictable, open, and timely processes for ballot issues. Petitions and ballot statements must be approved within 90 days of the initial submission, and legal challenges to ballot qualification must be resolved before the deadline for finalizing ballots. CI-133 requires the state to allow ample time for signature gathering, prohibits disqualification of petitions because of minor or technical issues, allows voters to withdraw their signatures if they so choose, and prohibits the use of government resources to support or oppose a ballot measure.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://sosmt.gov/wp-admin/admin-ajax.php?juwpfisadmin=false&action=wpfd&task=file.download&wpfd_category_id=35&wpfd_file_id=77619&token=c4ef8b9f51434e00a7a58950f02fec1f&preview=1","guide":"https://sosmt.gov/elections/vip/"},{"designation":"I-194","title":"Initiative No. 194: A Law Proposed by Initiative Petition","text":"I-194, if passed, limits the powers of artificial persons to those powers necessary or convenient as provided by law. These powers must exclude contributing anything of value to candidate elections, supporting or opposing political parties, or supporting or opposing state or local ballot issues. Artificial persons include non-profits, trusts, partnerships, corporations, trade associations, or unincorporated associations and includes all such entities doing business in Montana. Any violation of I-194 is punished by forfeiting all privileges to do business in Montana. Those privileges may be, but are not automatically, restored upon disgorgement and certification of compliance with I-194. I-194 does not apply to the distribution of news, commentary, or editorial content. I-194 also does not apply to the state of Montana, political subdivisions, individuals, political committees, or public corporations.","kind":"Statute","origin":"a citizens' petition","source":"https://sosmt.gov/wp-admin/admin-ajax.php?juwpfisadmin=false&action=wpfd&task=file.download&wpfd_category_id=35&wpfd_file_id=77619&token=c4ef8b9f51434e00a7a58950f02fec1f&preview=1","guide":"https://sosmt.gov/elections/vip/"}]},"NC":{"has":true,"by":"North Carolina State Board of Elections","read":"2026-10-19","list":{"url":"https://s3.amazonaws.com/dl.ncsbe.gov/Elections/2026/Candidate%20Filing/statewide_referendums_20261103.pdf","title":"Referendum Choices List Grouped by Referendum, November 3, 2026 (State Board of Elections)"},"guide":{"url":"https://www.beaufortncboe.org/sites/beaufortncboe.org/files/attachments/2026-09/2026_11_03_Summary%20Explanation%20of%20Constitutional%20Amendments.pdf","title":"Official Summary Explanation of 2026 Constitutional Amendments (Legislative Services Officer), as posted by the Beaufort County Board of Elections"},"measures":[{"designation":"CONSTITUTIONAL AMENDMENT - REQUIRE PHOTO ID FOR VOTING","title":"Require Photo ID for All Voters Proposed Constitutional Amendment","text":"Constitutional amendment to require all voters, not just those presenting to vote in person, to present photo identification before voting.","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://s3.amazonaws.com/dl.ncsbe.gov/Elections/2026/Candidate%20Filing/statewide_referendums_20261103.pdf","guide":"https://www.beaufortncboe.org/sites/beaufortncboe.org/files/attachments/2026-09/2026_11_03_Summary%20Explanation%20of%20Constitutional%20Amendments.pdf"},{"designation":"CONSTITUTIONAL AMENDMENT - MAXIMUM INCOME TAX RATE OF 3.5%","title":"Lower Taxes for All NC Proposed Constitutional Amendment","text":"Constitutional amendment to keep the State income tax rate from being raised higher than three and one-half percent (3.5%).","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://s3.amazonaws.com/dl.ncsbe.gov/Elections/2026/Candidate%20Filing/statewide_referendums_20261103.pdf","guide":"https://www.beaufortncboe.org/sites/beaufortncboe.org/files/attachments/2026-09/2026_11_03_Summary%20Explanation%20of%20Constitutional%20Amendments.pdf"},{"designation":"CONSTITUTIONAL AMENDMENT - PROPERTY TAX LEVY LIMIT","title":"Property Tax Levy Limit Proposed Constitutional Amendment","text":"Constitutional amendment requiring limits on property tax increases by local governments.","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://s3.amazonaws.com/dl.ncsbe.gov/Elections/2026/Candidate%20Filing/statewide_referendums_20261103.pdf","guide":"https://www.beaufortncboe.org/sites/beaufortncboe.org/files/attachments/2026-09/2026_11_03_Summary%20Explanation%20of%20Constitutional%20Amendments.pdf"}]},"ND":{"has":true,"by":"North Dakota Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.nd.gov/elections/voter/ballot-measures/measures-ballot","title":"Measures on Ballot | Secretary of State | North Dakota"},"guide":{"url":"https://www.sos.nd.gov/sites/default/files/documents/elections/2026-general-measure-guide.pdf","title":"North Dakota Statewide Ballot Measure Information, 2026 General Election (Secretary of State)"},"measures":[{"designation":"Constitutional Measure No. 1","title":"Constitutional Measure No. 1 (House Concurrent Resolution No. 3003, 2025 Session Laws, Ch. 614)","text":"This constitutional measure would amend and reenact section 9 of article III and section 16 of article IV of the Constitution of North Dakota. The proposed amendment would require constitutional amendments submitted to the electors, by resolution adopted by the legislative assembly proposing a constitutional amendment and each initiative petition and measure proposing a constitutional amendment, to receive an affirmative vote of at least sixty percent of those voting on the question for enactment. The estimated fiscal impact of this measure is none.","kind":"Constitutional amendment","origin":"the Legislative Assembly","source":"https://www.sos.nd.gov/sites/default/files/documents/elections/measures/ballot-language-2026-general-measure1.pdf","guide":"https://www.sos.nd.gov/sites/default/files/documents/elections/2026-general-measure-guide.pdf"},{"designation":"Initiated Constitutional Measure No. 2","title":null,"text":"This initiated measure amendment would amend and add a new section to article VIII of the North Dakota Constitution. It would mandate all public school districts, public schools, and public charter schools to provide one breakfast and one lunch each school day to enrolled students at no cost to the student, parent, or guardians. It would allow nonpublic schools, Bureau of Indian Education schools, and other tribal schools the option to provide the same. It would require the State of North Dakota to reimburse school districts and schools at one hundred percent of the current rates used by the state for free meals, and the rate shall be adjusted annually for inflation. It would require the legislative assembly to identify a source of funds for reimbursement and if a source of funds is unable to be identified, reimbursement funds would be appropriated from the legacy earnings fund. This amendment would supersede any other part of the constitution that conflicts with it. The estimated fiscal impact of this measure is a $124.3 million to $134.3 million increase in ongoing biennial expenditures for the 2027-2029 biennium and will be adjusted for inflation every year after that.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.sos.nd.gov/sites/default/files/documents/elections/measures/ballot-language-2026-general-measure2.pdf","guide":"https://www.sos.nd.gov/sites/default/files/documents/elections/2026-general-measure-guide.pdf"}]},"NE":{"has":true,"by":"Nebraska Secretary of State","read":"2026-10-19","list":{"url":"https://sos.nebraska.gov/elections","title":"2026 Elections | Nebraska Secretary of State"},"guide":{"url":"https://sos.nebraska.gov/sites/default/files/doc/elections/2026/2026%20Ballot%20Measures%20Pamphlet.pdf","title":"Informational Pamphlet on Initiative Measures Appearing on the 2026 General Election Ballot (Nebraska Secretary of State)"},"measures":[{"designation":"Proposed Amendment No. 1","title":"Proposed Constitutional Amendment","text":"A vote FOR will amend the state constitution to increase the term limit for state legislators from two consecutive four-year terms (eight years) to three consecutive four-year terms (12 years). A vote AGAINST will not amend the Nebraska Constitution, so the current limit of two consecutive four-year terms will remain in effect. State legislators will continue to be ineligible for office in the Legislature for four years after serving two consecutive terms. A constitutional amendment to change the limit on legislative terms from two consecutive terms to three consecutive terms.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.votedouglascounty-ne.gov/elections/2026/General/GN26SampleBallot.pdf"},{"designation":"Initiative Measure 440","title":"Online Sports Wagering Authorization (440)","text":"A vote \"FOR\" will amend the Nebraska Constitution to authorize the enactment of laws to allow persons located within Nebraska to place sports wagers through an Internet-based platform when offered by an authorized gaming operator conducting games of chance within a licensed racetrack enclosure in Nebraska. A vote \"AGAINST\" means the Nebraska Constitution will not be amended in this manner. Shall the Nebraska Constitution be amended to authorize the enactment of laws allowing persons located within Nebraska to place sports wagers through an Internet-based platform when offered by an authorized gaming operator conducting games of chance within a licensed racetrack enclosure in Nebraska?","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://sos.nebraska.gov/sites/default/files/doc/elections/2026/2026%20Ballot%20Measures%20Pamphlet.pdf","guide":"https://sos.nebraska.gov/sites/default/files/doc/elections/2026/2026%20Ballot%20Measures%20Pamphlet.pdf"},{"designation":"Initiative Measure 441","title":"Online Sports Wagering Regulation (441)","text":"A vote \"FOR\" will enact statutes allowing persons located within Nebraska to place sports wagers through an Internet-based platform when offered by an authorized gaming operator conducting games of chance within a licensed racetrack enclosure in Nebraska or the operator's platform provider, and regulating such sports wagers. A vote \"AGAINST\" means no such statutes will be enacted. Shall statutes be enacted that: (1) Allow persons located within Nebraska to place sports wagers through an Internet-based platform when offered by an authorized gaming operator conducting games of chance within a licensed racetrack enclosure in Nebraska or the operator's platform provider; and (2) Regulate such sports wagers?","kind":"Statute","origin":"a citizens' petition","source":"https://sos.nebraska.gov/sites/default/files/doc/elections/2026/2026%20Ballot%20Measures%20Pamphlet.pdf","guide":"https://sos.nebraska.gov/sites/default/files/doc/elections/2026/2026%20Ballot%20Measures%20Pamphlet.pdf"},{"designation":"Initiative Measure 442","title":"Fairness for Girls (442)","text":"A vote \"FOR\" will amend the Nebraska Constitution to provide: (1) Schools must expressly designate each athletic team or sport as one of the following based on biological sex: (a) Males, men, or boys; (b) females, women, or girls; or (c) coed or mixed; and (2) Athletic teams or sports designated for females, women, or girls shall not be open to students of the male sex. The amendment would apply to all athletic teams or sports sponsored by public schools or postsecondary educational institutions, and private schools or educational institutions whose athletic teams or sports compete against public schools or institutions. A vote \"AGAINST\" means the Nebraska Constitution will not be amended in this manner. Shall the Nebraska Constitution be amended to provide: (1) Schools must expressly designate each athletic team or sport as one of the following based on biological sex: (a) Males, men, or boys; (b) females, women, or girls; or (c) coed or mixed; and (2) Athletic teams or sports designated for females, women, or girls shall not be open to students of the male sex? The amendment would apply to all athletic teams or sports sponsored by public schools or postsecondary educational institutions, and private schools or educational institutions whose athletic teams or sports compete against public schools or institutions.","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://sos.nebraska.gov/sites/default/files/doc/elections/2026/2026%20Ballot%20Measures%20Pamphlet.pdf","guide":"https://sos.nebraska.gov/sites/default/files/doc/elections/2026/2026%20Ballot%20Measures%20Pamphlet.pdf"}]},"NH":{"has":true,"by":"New Hampshire Secretary of State","read":"2026-10-19","list":{"url":"https://mm.nh.gov/files/uploads/sos/docs/questions-on-general-election-ballot-2026-for-web.pdf","title":"Questions on the General Election Ballot, 2026 General Election (New Hampshire Secretary of State)"},"measures":[{"designation":"Question 1 (CACR 13)","title":null,"text":"Are you in favor of eliminating the office of register of probate by amending articles 71 and 81 of the second part of the constitution to read as follows: [Art.] 71. [County Treasurers, County Attorneys, Sheriffs, and Registers of Deeds Elected.] The county treasurers, county attorneys, sheriffs and registers of deeds, shall be elected by the inhabitants of the several towns, in the several counties in the State, according to the method now practiced, and the laws of the state, provided nevertheless the legislature shall have authority to alter the manner of certifying the votes, and the mode of electing those officers; but not so as to deprive the people of the right they now have of electing them. [Art.] 81. [Judges Not to Act as Counsel.] No judge shall be of counsel, act as advocate, or receive any fees as advocate or counsel, in any probate business which is pending, or may be brought into any court of probate in the county of which he or she is judge. (Passed by the N.H. House 325 Yes 15 No; Passed by the Senate 23 Yes 1 No) CACR 13","kind":"Constitutional amendment","origin":"the General Court","source":"https://mm.nh.gov/files/uploads/sos/docs/questions-on-general-election-ballot-2026-for-web.pdf"},{"designation":"Question 2 (Statutory Question required by HB 1300, Chapter 324, 2026)","title":null,"text":"Shall the [name of municipality] limit property tax growth for [name(s) of school district(s)] under RSA 32:5-i? If adopted for a two-year period: (1) the local property tax levy may not grow beyond the prior year's amount, adjusted for inflation and new construction; (2) SAU central office spending may not exceed 6 percent of total school district appropriations; and (3) bonded capital costs are excluded from both limits. These caps apply only to administrative operations of the SAU central office and do not affect classroom instruction, school-based services, or other municipal expenditures. These limits may be overridden as provided in RSA 32:5-i. Adoption requires a three-fifths (3/5) majority vote.","kind":"Question required by statute","origin":"the General Court","source":"https://mm.nh.gov/files/uploads/sos/docs/questions-on-general-election-ballot-2026-for-web.pdf","note":"The words in brackets are filled in on each ballot with the voter's own town or city and school district.","local":true}]},"NJ":{"has":false,"by":"Somerset County Clerk","read":"2026-10-19","list":{"url":"https://www.somersetcountynj.gov/home/showpublisheddocument/68125/639271590157170000","title":"Official 2026 General Election Sample Ballots, Somerset County (Somerset County Clerk)"},"none":{"from":"ballots"}},"NM":{"has":true,"by":"New Mexico Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.nm.gov/wp-content/uploads/2026/09/IT-0976-1A06E285BD1-1EA01218E0D402F2F5-2026-CA-and-GOB-Questions-final.pdf","title":"2026 General Election: Statewide Constitutional Amendments and General Obligation Bonds (New Mexico Secretary of State)"},"guide":{"url":"https://www.nmlegis.gov/Publications/New_Mexico_State_Government/Constitutional_Amendment/Constitutional_Amendments_2026.pdf","title":"Summary of and Arguments For & Against the Constitutional Amendments Proposed by the Legislature in 2025 and 2026 (New Mexico Legislative Council Service)"},"measures":[{"designation":"Constitutional Amendment 1","title":"Proposing an amendment to Article 4, Section 22 of the Constitution of New Mexico to require the governor to provide veto messages on all bills vetoed in whole or in part and to provide that all bills passed by the legislature and not acted on by the governor will become law.","text":"Proposing an amendment to Article 4, Section 22 of the Constitution of New Mexico to require the governor to provide veto messages on all bills vetoed in whole or in part and to provide that all bills passed by the legislature and not acted on by the governor will become law.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.nm.gov/wp-content/uploads/2026/09/IT-0976-1A06E285BD1-1EA01218E0D402F2F5-2026-CA-and-GOB-Questions-final.pdf","guide":"https://www.nmlegis.gov/Publications/New_Mexico_State_Government/Constitutional_Amendment/Constitutional_Amendments_2026.pdf"},{"designation":"Constitutional Amendment 2","title":"Proposing to amend Article 7, Section 1 of the Constitution of New Mexico to remove the requirement that school elections be separate from partisan elections.","text":"Proposing to amend Article 7, Section 1 of the Constitution of New Mexico to remove the requirement that school elections be separate from partisan elections.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.nm.gov/wp-content/uploads/2026/09/IT-0976-1A06E285BD1-1EA01218E0D402F2F5-2026-CA-and-GOB-Questions-final.pdf","guide":"https://www.nmlegis.gov/Publications/New_Mexico_State_Government/Constitutional_Amendment/Constitutional_Amendments_2026.pdf"},{"designation":"Constitutional Amendment 3","title":"Proposing an amendment to Article 12, Section 13 of the Constitution of New Mexico to establish nominating committees to provide lists of nominees to the governor for appointment of nonstudent members to the boards of regents of state educational institutions; providing that student members of boards of regents shall be appointed from a list provided by an elected student governing body of the institution; providing that, except for a student member, members of the boards of regents shall not have changed their political party registration in the twelve months preceding appointment.","text":"Proposing an amendment to Article 12, Section 13 of the Constitution of New Mexico to establish nominating committees to provide lists of nominees to the governor for appointment of nonstudent members to the boards of regents of state educational institutions; providing that student members of boards of regents shall be appointed from a list provided by an elected student governing body of the institution; providing that, except for a student member, members of the boards of regents shall not have changed their political party registration in the twelve months preceding appointment.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.nm.gov/wp-content/uploads/2026/09/IT-0976-1A06E285BD1-1EA01218E0D402F2F5-2026-CA-and-GOB-Questions-final.pdf","guide":"https://www.nmlegis.gov/Publications/New_Mexico_State_Government/Constitutional_Amendment/Constitutional_Amendments_2026.pdf"},{"designation":"Constitutional Amendment 4","title":"Proposing to amend Article 4, Section 10 of the Constitution of New Mexico to allow legislative compensation that is limited to the median household income for New Mexico, to require legislative compensation to be reduced if the median household income for New Mexico falls, to allow legislative compensation to be increased only if the median household income for New Mexico rises and to provide for delayed implementation.","text":"Proposing to amend Article 4, Section 10 of the Constitution of New Mexico to allow legislative compensation that is limited to the median household income for New Mexico, to require legislative compensation to be reduced if the median household income for New Mexico falls, to allow legislative compensation to be increased only if the median household income for New Mexico rises and to provide for delayed implementation.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.nm.gov/wp-content/uploads/2026/09/IT-0976-1A06E285BD1-1EA01218E0D402F2F5-2026-CA-and-GOB-Questions-final.pdf","guide":"https://www.nmlegis.gov/Publications/New_Mexico_State_Government/Constitutional_Amendment/Constitutional_Amendments_2026.pdf"},{"designation":"Bond Question 1","title":"The 2026 Capital Projects General Obligation Bond Act authorizes the issuance and sale of senior citizen facility improvement, construction and equipment acquisition bonds.","text":"The 2026 Capital Projects General Obligation Bond Act authorizes the issuance and sale of senior citizen facility improvement, construction and equipment acquisition bonds. Shall the state be authorized to issue general obligation bonds in an amount not to exceed twenty-one million five hundred eighty-two thousand two hundred thirteen dollars ($21,582,213) to make capital expenditures for certain senior citizen facility improvement, construction and equipment acquisition projects and provide for a general property tax imposition and levy for the payment of principal of, interest on and expenses incurred in connection with the issuance of the bonds and the collection of the tax as permitted by law?","kind":"Bond","origin":"the Legislature","source":"https://www.sos.nm.gov/wp-content/uploads/2026/09/IT-0976-1A06E285BD1-1EA01218E0D402F2F5-2026-CA-and-GOB-Questions-final.pdf"},{"designation":"Bond Question 2","title":"The 2026 Capital Projects General Obligation Bond Act authorizes the issuance and sale of library acquisition bonds.","text":"The 2026 Capital Projects General Obligation Bond Act authorizes the issuance and sale of library acquisition bonds. Shall the state be authorized to issue general obligation bonds in an amount not to exceed nineteen million three hundred twenty-four thousand one hundred eighty-eight dollars ($19,324,188) to make capital expenditures for academic, public school, public and tribal library resource acquisitions and provide for a general property tax imposition and levy for the payment of principal of, interest on and expenses incurred in connection with the issuance of the bonds and the collection of the tax as permitted by law?","kind":"Bond","origin":"the Legislature","source":"https://www.sos.nm.gov/wp-content/uploads/2026/09/IT-0976-1A06E285BD1-1EA01218E0D402F2F5-2026-CA-and-GOB-Questions-final.pdf"},{"designation":"Bond Question 3","title":"The 2026 Capital Projects General Obligation Bond Act authorizes the issuance and sale of higher education, special schools and tribal schools capital improvement and acquisition bonds.","text":"The 2026 Capital Projects General Obligation Bond Act authorizes the issuance and sale of higher education, special schools and tribal schools capital improvement and acquisition bonds. Shall the state be authorized to issue general obligation bonds in an amount not to exceed three hundred fifty-two million two hundred twenty five thousand three hundred seventy-nine dollars ($352,225,379) to make capital expenditures for certain higher education, special schools and tribal schools capital improvements and acquisitions and provide for a general property tax imposition and levy for the payment of principal of, interest on and expenses incurred in connection with the issuance of the bonds and the collection of the tax as permitted by law?","kind":"Bond","origin":"the Legislature","source":"https://www.sos.nm.gov/wp-content/uploads/2026/09/IT-0976-1A06E285BD1-1EA01218E0D402F2F5-2026-CA-and-GOB-Questions-final.pdf"}]},"NV":{"has":true,"by":"Nevada Secretary of State","read":"2026-10-19","list":{"url":"https://www.nvsos.gov/elections/2026-petitions","title":"2026 Petitions & General Election Ballot Questions (Nevada Secretary of State)"},"guide":{"url":"https://www.nvsos.gov/home/showpublisheddocument/20519/639233354596030000","title":"2026 Ballot Question Guide (Nevada Secretary of State)"},"measures":[{"designation":"State Question No. 6","title":"Amendment to the Nevada Constitution (Initiative Petition C-05-2023)","text":"Should the Nevada Constitution be amended to create an individual's fundamental right to an abortion, without interference by state or local governments, whenever the abortion is performed by a qualified healthcare professional until fetal viability or when necessary to protect the health or life of the pregnant individual at any point during the pregnancy?","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.clarkcountynv.gov/adobe/assets/urn:aaid:aem:e74294d7-218d-41cc-995f-0e16bc0a9e1f/original/as/all-quests-26g.pdf","guide":"https://www.clarkcountynv.gov/adobe/assets/urn:aaid:aem:e74294d7-218d-41cc-995f-0e16bc0a9e1f/original/as/all-quests-26g.pdf"},{"designation":"State Question No. 7","title":"Amendment to the Nevada Constitution (Initiative Petition C-02-2023)","text":"Should the Nevada Constitution be amended to require voters to either present photo identification to verify their identity when voting in-person or to provide certain personal information to verify their identity when voting by mail ballot?","kind":"Constitutional amendment","origin":"a citizens' petition","source":"https://www.clarkcountynv.gov/adobe/assets/urn:aaid:aem:e74294d7-218d-41cc-995f-0e16bc0a9e1f/original/as/all-quests-26g.pdf","guide":"https://www.clarkcountynv.gov/adobe/assets/urn:aaid:aem:e74294d7-218d-41cc-995f-0e16bc0a9e1f/original/as/all-quests-26g.pdf"}]},"NY":{"has":false,"by":"Board of Elections in the City of New York","read":"2026-10-19","list":{"url":"https://www.vote.nyc/sites/default/files/pdf/Ballot_Proposals/GE2026/Appendix_A_Proposed_Ballot_Questions_20260723_ENGLISH.pdf","title":"Appendix A, Proposed Questions, 2026 General Election (Board of Elections in the City of New York)"},"none":{"from":"list"}},"OH":{"has":true,"by":"Ohio Secretary of State","read":"2026-10-19","list":{"url":"https://www.ohiosos.gov/assets/dir2026-45-form-of-the-official-ballot-for-the-november%203-general-election.pdf","title":"Directive 2026-45, Form of the Official Ballot for the November 3, 2026, General Election (Ohio Secretary of State, August 25, 2026)"},"guide":{"url":"https://www.ohiosos.gov/office/duties-and-responsibilities/ohio-ballot-board/currently-circulating-petitions#general-assembly-initiated","title":"Ohio Ballot Board: To Require Voters to Present Photo Identification in Order to Vote (Sub. S.J.R. 10)"},"measures":[{"designation":"Issue 3","title":"To Require Voters to Present Photo Identification in Order to Vote","text":"This proposed amendment would: • Require voters to present an approved form of government-issued photo identification in order to vote. • Allow state law to provide for an alternative method of verifying a voter’s identity for a voter who has a sincere religious objection to being photographed and, therefore, does not possess an approved form of government-issued photo identification. • Require that voters who do not vote in person provide an approved form of government-issued photo identification, unless the law authorizes those persons to vote by providing a signature and at least one other specified unique identifier. • Define approved forms of government-issued photo identification as an unexpired Ohio driver license or state identification card; a United States passport or passport card; or a United States military identification card, Ohio National Guard identification card, or United States Department of Veterans Affairs identification card. If approved, the amendment shall take effect immediately. A \"YES\" vote means approval of the amendment. A \"NO\" vote means disapproval of the amendment. SHALL THE AMENDMENT BE APPROVED?","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.ohiosos.gov/assets/certified-ballot-language-08-03-2026.pdf","guide":"https://www.ohiosos.gov/office/duties-and-responsibilities/ohio-ballot-board/currently-circulating-petitions#general-assembly-initiated"}]},"OK":{"has":true,"by":"Oklahoma State Election Board","read":"2026-10-19","list":{"url":"https://oklahoma.gov/elections/elections-results/state-question-info.html","title":"State Questions (Oklahoma State Election Board)"},"measures":[{"designation":"State Question 845, Legislative Referendum 379","title":"Judicial Nominating Commission","text":"This measure amends article 7-B, section 3 of the Oklahoma Constitution, changing the Judicial Nominating Commission’s structure. Currently appointments are based on congressional districts as constituted in 1967. If approved, appointments to the fifteen-member Commission will be as follows: 1) Governor appoints six members, including one from each congressional district as of the time of their appointment; 2) the Oklahoma Bar Association appoints six members, including one from each congressional district as of the date of selection; and 3) no less than eight members select three at-large members. The measure will permit any number of the commissioners to be licensed attorneys in Oklahoma or another state. The prohibition against immediate family members from practicing law will be removed. The measure changes terms so that at-large commissioners would serve a two-year term, and all other commissioners would serve a six-year term. Additionally, it removes restrictions on political party membership for members appointed by the Governor and at-large members. The measure also permits a commissioner to succeed himself or herself. Vacancies will be filled in the same manner as a commissioner is appointed or selected for the remainder of the relevant term. This measure will not have a fiscal impact. Shall the proposal be approved?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.oklahoma.gov/content/dam/ok/en/elections/state-questions/sq2026/sq845-final-ballot-title-accessible.pdf"},{"designation":"State Question 847, Legislative Referendum 381","title":"Real Property Valuation","text":"This measure amends article 10, sections 8B and 8C of the Oklahoma Constitution. Currently, section 8B limits annual growth in fair cash value to 5% for most real property or 3% for homesteads and agricultural land. If approved, the measure would limit annual growth in fair cash value for tax year 2027 and after to 4% for most real property or 1.75% for homesteads and agricultural land. Currently, section 8C prohibits any increase in fair cash value of homestead property for persons age sixty-five (65) or older whose income does not exceed certain limits, sometimes referred to as the “senior freeze.” Instead of prohibiting any increase in fair cash value for these homesteads, there would be an annual limit of 1.75%. The measure eliminates the income cap on gross household income to qualify for the senior freeze. If approved, the annual limit on an increase in fair cash value would be tied to how much gross household income the homestead owner had in the preceding year. If a homeowner’s gross household income from the previous year was at or below the median income for their county or area (as determined by the U.S. Department of Housing and Urban Development’s estimated median income amount for the county or metropolitan statistical area), a homeowner’s homestead fair cash value cannot be increased. If the income amount was in excess of certain thresholds, the limit on increases in fair cash value for homesteads owned by persons age 65 or older could be 0.35% (income over 100% up to 120%); 0.7% (income over 120% up to 140%); 1.05% (income over 140% up to 160%); 1.4% (income over 160% up to 180%); or 1.75% (income over 180%). If passed, this measure would have a fiscal impact on the state, but the exact impact is unknown. Shall the proposal be approved?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.sos.ok.gov/documents/questions/847.pdf"}]},"OR":{"has":false,"by":"Oregon Secretary of State","read":"2026-10-19","list":{"url":"https://sos.oregon.gov/elections/Pages/current-election.aspx","title":"General Election – November 3, 2026 (Oregon Secretary of State, Elections Division)"},"guide":{"url":"https://sos.oregon.gov/elections/Voters-Pamphlet/Pages/Voters-Pamphlet-English.aspx","title":"General Election: November 3, 2026 State Voters' Pamphlet (English)"},"none":{"from":"statement","words":"There are no statewide ballot measures on the ballot this election."}},"PA":{"has":null,"by":"Pennsylvania Department of State","read":"2026-10-19","office":{"url":"https://www.pa.gov/agencies/vote/elections/upcoming-elections","name":"Pennsylvania Department of State, Upcoming Elections"}},"PR":{"has":null,"by":"Comisión Estatal de Elecciones","read":"2026-10-19","office":{"url":"https://www.ceepur.org/eventoscee/","name":"Comisión Estatal de Elecciones, Eventos Electorales"}},"RI":{"has":true,"by":"Rhode Island Department of State","read":"2026-10-19","list":{"url":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf","title":"Voter Information Handbook: A Guide to State Referenda and Voting Procedures in Rhode Island, General Election November 3, 2026 (Rhode Island Department of State)"},"guide":{"url":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf","title":"Rhode Island Voter Information Handbook, General Election November 3, 2026"},"measures":[{"designation":"Question 1","title":"HIGHER EDUCATION FACILITIES - $275,000,000","text":"1. HIGHER EDUCATION FACILITIES - $275,000,000 For capital improvements to higher education facilities, to be allocated as follows: a. University of Rhode Island Integrated Health Building - $165,000,000 b. Rhode Island College Adams Library Renovations - $50,000,000 c. Community College of Rhode Island Workforce Innovation Center - $60,000,000","kind":"Bond","origin":"the General Assembly","source":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf","guide":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf#page=9"},{"designation":"Question 2","title":"HOUSING AND HOMEOWNERSHIP - $120,000,000","text":"2. HOUSING AND HOMEOWNERSHIP - $120,000,000 To increase and preserve the availability of affordable and accessible housing to meet the needs of all Rhode Islanders and support community revitalization through the redevelopment of existing structures, new construction, property acquisition, and infrastructure improvements. Of this amount, at least twenty-five million dollars ($25,000,000) shall be allocated towards increasing production of housing intended for homeownership and up to ten million dollars ($10,000,000) may be used to support a program for public housing development.","kind":"Bond","origin":"the General Assembly","source":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf","guide":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf#page=11"},{"designation":"Question 3","title":"ECONOMIC DEVELOPMENT - $100,000,000","text":"3. ECONOMIC DEVELOPMENT - $100,000,000 To fund site development and growth industry infrastructure for economic development purposes, to be allocated as follows: a. Site Development - $55,000,000 b. Growth Industry Infrastructure - $45,000,000","kind":"Bond","origin":"the General Assembly","source":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf","guide":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf#page=12"},{"designation":"Question 4","title":"CULTURAL ECONOMY - $50,000,000","text":"4. CULTURAL ECONOMY - $50,000,000 To provide funding for cultural economy efforts, to be allocated as follows: a. State History Center - $45,000,000 b. State Preservation Grants Program - $5,000,000","kind":"Bond","origin":"the General Assembly","source":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf","guide":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf#page=13"},{"designation":"Question 5","title":"GREEN ECONOMY BONDS - $55,000,000","text":"5. GREEN ECONOMY BONDS - $55,000,000 For environmental and recreational purposes, to be allocated as follows: a. Brownfields Remediation and Economic Development - $3,000,000 b. Facility Improvements - $12,000,000 c. Local Recreation Projects - $1,000,000 d. Marine Infrastructure Development - $1,000,000 e. Resilient Rhody Infrastructure Fund - $25,000,000 f. Narragansett Bay Watershed Restoration - $7,000,000 g. Agricultural Land Preservation Commission - $3,000,000 h. Open Space Program - $3,000,000","kind":"Bond","origin":"the General Assembly","source":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf","guide":"https://vote.sos.ri.gov/Forms/Elections/Guides/VoterRef26.pdf#page=14"}]},"SC":{"has":false,"by":"Georgetown County Board of Voter Registration and Elections","read":"2026-10-19","list":{"url":"https://www.gtcountysc.gov/DocumentCenter/View/4203/November-3-2026-General-Election-Sample-Ballots-PDF","title":"Official Ballot, Georgetown County, General Election, November 3, 2026 (Georgetown County Board of Voter Registration and Elections)"},"none":{"from":"ballots"}},"SD":{"has":true,"by":"South Dakota Secretary of State","read":"2026-10-19","list":{"url":"https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Information/2026-ballot-questions.aspx","title":"Potential Ballot Questions: 2026 General Election Ballot Measures (South Dakota Secretary of State)"},"guide":{"url":"https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Information/2026%20Ballot%20Question%20Information/2026%20Ballot%20Question%20Files/2026%20BQ/2026GeneralBQPamphletFINAL.pdf","title":"2026 Ballot Question Pamphlet (South Dakota Secretary of State)"},"measures":[{"designation":"Constitutional Amendment I","title":"An Amendment to the South Dakota Constitution that Repeals Expanded Medicaid Coverage if Federal Funding for the Program Drops below 90%.","text":"Medicaid is a program, funded by the State and the federal government, to provide medical coverage for low-income children, pregnant women, disabled individuals, and the elderly. In the 2022 General Election the voters approved Constitutional Amendment D, which expanded Medicaid eligibility in South Dakota. Amendment D requires the State to also provide Medicaid benefits to anyone over the age of 18 and under 65 whose income is at or below 133% of the federal property level, plus 5% of the federal poverty level for the applicable family size. Currently, federal law requires the federal government to fund 90% of South Dakota's Medicaid expansion. This proposed Constitutional Amendment ends the expanded Medicaid coverage if the federal funding for expansion drops below 90%. If federal funding drops below that 90% threshold, Medicaid coverage will once again only apply to low-income children, pregnant women, disabled individuals, and the elderly. Vote \"Yes\" to adopt the amendment. Vote \"No\" to leave the Constitution as it is.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Information/2026%20Ballot%20Question%20Information/2026%20Ballot%20Question%20Files/2026%20BQ/2026GeneralBQPamphletFINAL.pdf","guide":"https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Information/2026%20Ballot%20Question%20Information/2026%20Ballot%20Question%20Files/2026%20BQ/2026GeneralBQPamphletFINAL.pdf"},{"designation":"Constitutional Amendment J","title":"An Amendment to the South Dakota Constitution Clarifying that an Individual Must Be a Citizen of the United States to be Eligible to Vote.","text":"Article VII, § 2 of the South Dakota Constitution defines who is qualified to vote in state elections. Among these qualifications are age, residency, and United States citizenship requirements. Article VII, § 2 also establishes that individuals may be disqualified from voting because of mental incompetence or a felony conviction. This constitutional amendment adds people who are not United States citizens to the list of individuals disqualified from voting, clarifying the existing requirement that only citizens may vote in state elections. Vote \"Yes\" to adopt the amendment. Vote \"No\" to leave the Constitution as it is.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Information/2026%20Ballot%20Question%20Information/2026%20Ballot%20Question%20Files/2026%20BQ/2026GeneralBQPamphletFINAL.pdf","guide":"https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Information/2026%20Ballot%20Question%20Information/2026%20Ballot%20Question%20Files/2026%20BQ/2026GeneralBQPamphletFINAL.pdf"},{"designation":"Constitutional Amendment K","title":"An Amendment to the South Dakota Constitution Establishing the Trust for Unclaimed Property Fund.","text":"Under South Dakota statute, intangible property is presumed to be abandoned if it remains unclaimed by the owner for more than three years after it became payable or distributable. Examples of intangible property are traveler's checks, money orders, bank deposits, refunds, stocks, funds owed under a life insurance policy, and property held in a safe deposit box. Abandoned intangible property is transferred to the State Treasurer to hold while waiting for the owner to claim it. The State Treasurer must provide public notice of the abandoned property. This proposed constitutional amendment establishes a trust fund where unclaimed abandoned property will be deposited. Portions of the interest and income from this fund will be distributed into the general fund for the benefit of the state. This proposed amendment requires the Legislature to determine the amount to be distributed that promotes the growth of the trust fund and the distributed amount. Vote \"Yes\" to adopt the amendment. Vote \"No\" to leave the Constitution as it is.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Information/2026%20Ballot%20Question%20Information/2026%20Ballot%20Question%20Files/2026%20BQ/2026GeneralBQPamphletFINAL.pdf","guide":"https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Information/2026%20Ballot%20Question%20Information/2026%20Ballot%20Question%20Files/2026%20BQ/2026GeneralBQPamphletFINAL.pdf"},{"designation":"Constitutional Amendment L","title":"An Amendment to the South Dakota Constitution Requiring that a Proposed Constitutional Amendment or Revision Receive an Affirmative Vote of Sixty Percent of the Votes Cast.","text":"The State Constitution provides that any proposed constitutional amendment or revision must be submitted to the voters for approval. Currently, a proposed constitutional amendment or revision becomes part of the Constitution if approved by a majority of the votes cast. This proposed Constitutional Amendment increases the number of votes required for a proposed constitutional amendment or revision to become part of the Constitution. If passed, further constitutional amendments must receive an affirmative vote of sixty percent of the votes cast to be implemented. Vote \"Yes\" to adopt the amendment. Vote \"No\" to leave the Constitution as it is.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Information/2026%20Ballot%20Question%20Information/2026%20Ballot%20Question%20Files/2026%20BQ/2026GeneralBQPamphletFINAL.pdf","guide":"https://sdsos.gov/elections-voting/upcoming-elections/general-information/2026%20Election%20Information/2026%20Ballot%20Question%20Information/2026%20Ballot%20Question%20Files/2026%20BQ/2026GeneralBQPamphletFINAL.pdf"}]},"TN":{"has":true,"by":"Tennessee Secretary of State","read":"2026-10-19","list":{"url":"https://sos.tn.gov/elections/announcements/2026-proposed-constitutional-amendments","title":"Proposed Constitutional Amendments | Tennessee Secretary of State"},"measures":[{"designation":"Constitutional Amendment #1","title":null,"text":"Shall Article I, Section 15 of the Constitution of Tennessee be amended by deleting the following: That all prisoners shall be bailable by sufficient sureties, unless for capital offences, when the proof is evident, or the presumption great. And the privilege of the writ of Habeas Corpus shall not be suspended, unless when in case of rebellion or invasion, the General Assembly shall declare the public safety requires it. and substituting instead the following: (a) All prisoners shall be bailable by sufficient sureties unless for the following when the proof is evident or the presumption great: (1) A capital offense; (2) An act of terrorism; (3) Second degree murder; (4) Aggravated rape of a child; (5) Aggravated rape; (6) Grave torture; and (7) Any other offense for which, as of November 3, 2026, a defendant, if convicted, could not be released prior to the expiration of at least eighty-five percent of the entire sentence imposed. (b) In any case in which bail for an offense listed in subsection (a) is granted or denied before conviction, the judge or magistrate shall place in the record the judge's or magistrate's reasons for granting or denying bail. (c) The privilege of the writ of Habeas Corpus shall not be suspended, unless when in case of rebellion or invasion, the General Assembly shall declare the public safety requires it.","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://sos.tn.gov/elections/announcements/2026-proposed-constitutional-amendments"},{"designation":"Constitutional Amendment #2","title":null,"text":"Shall Article II, Section 28 of the Constitution of the State of Tennessee be amended by deleting the following language from the first sentence: In accordance with the following provisions, all property real, personal or mixed shall be subject to taxation, but the Legislature and substituting instead the following: In accordance with the following provisions, all property real, personal, or mixed shall be subject to taxation, but the Legislature shall not levy, authorize, or otherwise permit any state tax upon such property, and the Legislature","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://sos.tn.gov/elections/announcements/2026-proposed-constitutional-amendments"},{"designation":"Constitutional Amendment #3","title":null,"text":"Shall Article I, Section 35 of the Constitution of Tennessee be amended by deleting the section in its entirety and substituting the following: Section 35. That to preserve and protect the rights of victims of crime to justice and due process throughout the criminal and juvenile justice systems, a victim, as defined by law and which may be expanded by the General Assembly, shall have the following rights, which shall be protected: (1) The right to be treated with fairness for the victim's safety and dignity; (2) The right, upon request, to reasonable notice of all public criminal proceedings and all public juvenile delinquency proceedings involving the accused; (3) The right to be present at all public criminal proceedings and all public juvenile delinquency proceedings involving the accused; (4) The right upon request to be heard in any proceeding involving release, plea, sentencing, disposition, and parole, as well as any public proceeding when relevant during which a right of the victim is implicated; (5) The right to be heard and informed of all parole procedures, to participate in the parole process, to provide information to the parole authority to be considered before the parole of the offender, and to be notified, upon request, of the parole or other release of the offender; (6) The right to be free from harassment, intimidation, and abuse throughout the criminal justice system, including reasonable protection, as defined by the General Assembly, from the accused or any person acting on behalf of the accused; (7) The right, upon request, to reasonable notice of any release, transfer, or escape of the accused or convicted person; (8) The right to full and timely restitution from the offender; (9) The right to a speedy trial or disposition and a prompt and final conclusion of the case after the conviction or sentence; (10) The right to be informed of the minimum sentence the offender will serve in custody and the scheduled release date; (11) The right to have the safety of the victim, the victim's family, and the general public considered before any parole or other post-judgment release decision is made; (12) The right, upon request, to confer with the prosecution; and (13) The right to be fully informed of all rights afforded to crime victims. A victim may assert the rights enumerated in this section, not as a party, but in the manner further provided by the General Assembly protecting the victim's right to standing. The General Assembly has the authority to enact substantive and procedural laws to further define, implement, preserve, and protect the rights guaranteed to victims by this section. This section must be interpreted to preserve and protect the rights of all persons to due process. This section, or any law enacted under this section, does not create a basis for vacating a conviction. This section does not restrict the powers of the District Attorney General or the inherent authority of the court. Other than as provided in the preceding paragraph, this section does not create a cause of action or claim for damages against the state or a political subdivision of the state; an officer, employee, or agent of the state or of any of its political subdivisions; or an officer or employee of the court.","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://sos.tn.gov/elections/announcements/2026-proposed-constitutional-amendments"}]},"TX":{"has":false,"by":"Texas Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.texas.gov/elections/forms/2026-sample-ballot.pdf","title":"General Election Sample Ballot, November 3, 2026 (Texas Secretary of State)"},"none":{"from":"ballots"}},"UT":{"has":true,"by":"Utah Lieutenant Governor","read":"2026-10-19","list":{"url":"https://www.utah.gov/pmn/files/1494271.pdf","title":"Utah's Official Voter Information Pamphlet, General Election, November 3, 2026 (Office of the Lieutenant Governor)"},"guide":{"url":"https://www.utah.gov/pmn/files/1494271.pdf","title":"Utah's Official Voter Information Pamphlet, General Election 2026 (Office of the Lieutenant Governor)"},"measures":[{"designation":"Constitutional Amendment A","title":"Proposal to Amend Utah Constitution - Publication Amendments","text":"Shall the Utah Constitution be amended to change how proposed constitutional amendments are published, requiring publication for 60 days immediately before the general election in a manner established by state law instead of in newspapers? If voters approve Constitutional Amendment A, state statute would change to require the Lieutenant Governor to publish the full text of all proposed constitutional amendments and other ballot questions from the Legislature, on the Utah Public Notice Website and on the Lieutenant Governor's website for 60 days immediately before the general election.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.utah.gov/pmn/files/1494271.pdf","guide":"https://www.utah.gov/pmn/files/1494271.pdf"},{"designation":"Constitutional Amendment B","title":"Proposal to Amend Utah Constitution - Statewide Initiatives","text":"Shall the Utah Constitution be amended to require that citizen-proposed laws that increase taxes compared to existing law be approved by at least 60% of voters, instead of a simple majority?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://www.utah.gov/pmn/files/1494271.pdf","guide":"https://www.utah.gov/pmn/files/1494271.pdf"}]},"VA":{"has":true,"by":"Virginia Department of Elections","read":"2026-10-19","list":{"url":"https://www.elections.virginia.gov/casting-a-ballot/candidate-list/november-2026-proposed-constitutional-amendments/","title":"November 2026 Proposed Constitutional Amendments and Local Referenda (Virginia Department of Elections)"},"guide":{"url":"https://www.elections.virginia.gov/media/formswarehouse/print-ready-materials-artwork/november-2026-proposed-constitutional-amendments/2026-Nov-Proposed-Constitution-Amendments-Brochure---EN.pdf","title":"Proposed Constitutional Amendments Brochure (Virginia Department of Elections, November 3, 2026)"},"measures":[{"designation":"Question 1","title":"Proposed Constitutional Amendment Question 1","text":"Should the Constitution of Virginia be amended to (i) protect the freedom to make personal decisions about prenatal care, childbirth, postpartum care, birth control, abortion, miscarriage management, and fertility care; (ii) protect doctors, nurses, and patients from being punished for these decisions; and (iii) allow for restrictions on access to abortion during the third trimester of pregnancy except when the patient's health is at risk or the pregnancy cannot survive?","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.elections.virginia.gov/election-law/proposed-constitutional-amendment-question-1/","guide":"https://www.elections.virginia.gov/election-law/proposed-constitutional-amendment-question-1/"},{"designation":"Question 2","title":"Proposed Constitutional Amendment Question 2","text":"Should the Constitution of Virginia be amended to (i) remove the ban on same-sex marriage; (ii) affirm that two adults may marry regardless of sex, gender, or race; and (iii) require all legally valid marriages to be treated equally under the law?","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.elections.virginia.gov/election-law/proposed-constitutional-amendment-question-2/","guide":"https://www.elections.virginia.gov/election-law/proposed-constitutional-amendment-question-2/"},{"designation":"Question 3","title":"Proposed Constitutional Amendment Question 3","text":"Should the Constitution of Virginia be amended (i) to provide for the fundamental right to vote in the Commonwealth, (ii) to revise the qualifications of voters so that a person convicted of a felony is not entitled to vote during his period of incarceration but is automatically invested with the right to vote upon release from incarceration, and (iii) to update the existing prohibition on voting by persons found to be mentally incompetent to instead apply to persons who have been found to lack the capacity to understand the act of voting?","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.elections.virginia.gov/election-law/proposed-constitutional-amendment-question-3/","guide":"https://www.elections.virginia.gov/election-law/proposed-constitutional-amendment-question-3/"}]},"VI":{"has":false,"by":"Elections System of the Virgin Islands","read":"2026-10-19","list":{"url":"https://vivote.gov/wp-content/uploads/2026/09/2026-General-Election-St.-Croix-District.pdf","title":"Sample Ballots, General Election, November 3, 2026: St. Croix District and St. Thomas/St. John District (Elections System of the Virgin Islands)"},"none":{"from":"ballots"}},"VT":{"has":true,"by":"Office of the Governor of Vermont","read":"2026-10-19","list":{"url":"https://governor.vermont.gov/press-release/governor-phil-scott-formally-proclaims-constitutional-amendment-proposals-3-and-4","title":"Governor Phil Scott Formally Proclaims Constitutional Amendment Proposals 3 and 4 Will Appear on November Ballot (Office of the Governor, press release, July 28, 2026)"},"guide":{"url":"https://sos.vermont.gov/elections/voters/voter-guide","title":"Vermont Voter Guide (Vermont Secretary of State)"},"measures":[{"designation":"Proposal 3","title":"Article 23. [Right to collectively bargain]","text":"To see if the voters will amend the Vermont Constitution by adding Article 23 to read: Article 23. [Right to collectively bargain] That employees have a right to organize or join a labor organization for the purpose of collectively bargaining with their employer through an exclusive representative of their choosing for the purpose of negotiating wages, hours, and working conditions and to protect their economic welfare and safety in the workplace. Therefore, no law shall be adopted that interferes with, negates, or diminishes the right of employees to collectively bargain with respect to wages, hours, and other terms and conditions of employment and workplace safety, or that prohibits the application or execution of an agreement between an employer and a labor organization representing the employer's employees that requires membership in the labor organization as a condition of employment.","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.edenvt.org/wp-content/uploads/2026/09/Sample-Ballot.pdf"},{"designation":"Proposal 4","title":"Article 23. [Equality of rights]","text":"To see if the voters will amend the Vermont Constitution by adding Article 23 to read: Article 23. [Equality of rights] That the people are guaranteed equal protection under the law. The State shall not deny equal treatment under the law on account of a person's race, ethnicity, sex, religion, disability, sexual orientation, gender identity, gender expression, or national origin. Nothing in this Article shall be interpreted or applied to prevent the adoption or implementation of measures intended to provide equality of treatment and opportunity for members of groups that have historically been subject to discrimination.","kind":"Constitutional amendment","origin":"the General Assembly","source":"https://www.edenvt.org/wp-content/uploads/2026/09/Sample-Ballot.pdf"}]},"WA":{"has":true,"by":"Washington Secretary of State","read":"2026-10-19","list":{"url":"https://www.sos.wa.gov/sites/default/files/2026-08/2026%20Certification%20of%20Measures%20to%20General%20Election.pdf","title":"2026 Certification of Measures to General Election (Washington Secretary of State, Elections Division)"},"guide":{"url":"https://www.sos.wa.gov/elections/data-research/election-data-and-maps/election-results-and-voters-pamphlets/2026-general-election-voters-guide","title":"2026 General Election Voters' Guide (Washington Secretary of State)"},"measures":[{"designation":"Initiative Measure No. IP26-645","title":"Initiative Measure No. IP26-645 concerns state and local taxes.","text":"Initiative Measure No. IP26-645 concerns state and local taxes. This measure would repeal a 9.9% tax on annual individual income over $1,000,000; prohibit taxes measured by individual income and taxes on individual income or the receipt of individual income; and define \"income.\" This measure would decrease funding for public K-12 education, higher education (including universities and community colleges), and human services (primarily healthcare). Should this measure be enacted into law?","kind":"Statute","origin":"a citizens' petition","source":"https://www.sos.wa.gov/sites/default/files/2026-10/Voters%20Pamphlet%202026%20-%20Edition%2027%20-%20Thurston.pdf","guide":"https://www.sos.wa.gov/sites/default/files/2026-10/Voters%20Pamphlet%202026%20-%20Edition%2027%20-%20Thurston.pdf"},{"designation":"Initiative Measure No. IL26-001","title":"Initiative Measure No. IL26-001 concerns parental rights relating to their children in public school.","text":"Initiative Measure No. IL26-001 concerns parental rights relating to their children in public school. This measure would repeal amendments to a statute listing certain rights of parents and guardians of public-school children and re-enact the law as it was originally enacted by Initiative to the Legislature 2081. Should this measure be enacted into law?","kind":"Statute","origin":"a citizens' petition","source":"https://www.sos.wa.gov/sites/default/files/2026-10/Voters%20Pamphlet%202026%20-%20Edition%2027%20-%20Thurston.pdf","guide":"https://www.sos.wa.gov/sites/default/files/2026-10/Voters%20Pamphlet%202026%20-%20Edition%2027%20-%20Thurston.pdf"},{"designation":"Initiative Measure No. IL26-638","title":"Initiative Measure No. IL26-638 concerns participation in athletics at K-12 schools.","text":"Initiative Measure No. IL26-638 concerns participation in athletics at K-12 schools. This measure would prohibit students it defines as \"biologically male\" from competing in certain school athletic activities intended for female students only. It would require verification of biological sex by students' healthcare providers. Should this measure be enacted into law?","kind":"Statute","origin":"a citizens' petition","source":"https://www.sos.wa.gov/sites/default/files/2026-10/Voters%20Pamphlet%202026%20-%20Edition%2027%20-%20Thurston.pdf","guide":"https://www.sos.wa.gov/sites/default/files/2026-10/Voters%20Pamphlet%202026%20-%20Edition%2027%20-%20Thurston.pdf"}]},"WI":{"has":true,"by":"Wisconsin Elections Commission","read":"2026-10-19","list":{"url":"https://elections.wi.gov/memo/type-c-notice-referendum-november-3-2026","title":"Type C Notice of Referendum for November 3, 2026 General Election (Wisconsin Elections Commission)"},"measures":[{"designation":"Question 1","title":"Partial veto","text":"Partial veto. Shall section 10 (1) (c) of article V of the constitution be amended to prohibit the governor, in exercising his or her partial veto authority, from creating or increasing or authorizing the creation or increase of any tax or fee?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://elections.wi.gov/sites/default/files/documents/Type%20C%20Notice%20for%20Ref%20for%20November%202026%20General%20Election_Final.pdf","guide":"https://elections.wi.gov/sites/default/files/documents/Type%20C%20Notice%20for%20Ref%20for%20November%202026%20General%20Election_Final.pdf"},{"designation":"Question 2","title":"Freedom to gather in places of worship during an emergency","text":"Freedom to gather in places of worship during an emergency. Shall section 18 of article I of the constitution, which deals with religious liberty, be amended to prohibit the state or a political subdivision of the state from ordering the closure of, or forbidding gatherings in, places of worship in response to a state of emergency, including a public health emergency?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://elections.wi.gov/sites/default/files/documents/Type%20C%20Notice%20for%20Ref%20for%20November%202026%20General%20Election_Final.pdf","guide":"https://elections.wi.gov/sites/default/files/documents/Type%20C%20Notice%20for%20Ref%20for%20November%202026%20General%20Election_Final.pdf"},{"designation":"Question 3","title":"Governmental entity discrimination prohibited","text":"Governmental entity discrimination prohibited. Shall section 27 of article I of the constitution be created to prohibit governmental entities in the state from discriminating against, or granting preferential treatment to, any individual or group on the basis of race, sex, color, ethnicity, or national origin in public employment, public education, public contracting, or public administration?","kind":"Constitutional amendment","origin":"the Legislature","source":"https://elections.wi.gov/sites/default/files/documents/Type%20C%20Notice%20for%20Ref%20for%20November%202026%20General%20Election_Final.pdf","guide":"https://elections.wi.gov/sites/default/files/documents/Type%20C%20Notice%20for%20Ref%20for%20November%202026%20General%20Election_Final.pdf"}]},"WV":{"has":true,"by":"West Virginia Secretary of State","read":"2026-10-19","list":{"url":"https://sos.wv.gov/article/kris-warner-clarifies-wv-secretary-states-role-proposed-constitutional-amendment-november","title":"Kris Warner clarifies the WV Secretary of State's role in proposed constitutional amendment on the November ballot (WV Secretary of State, October 1, 2026)"},"measures":[{"designation":"Amendment No. 1","title":"Citizenship Requirement to Vote in West Virginia Elections Amendment","text":"Summary of Purpose: This amendment provides that in all elections held in West Virginia only citizens of the United States who are citizens of this state are qualified to vote.","kind":"Constitutional amendment","origin":"the Legislature","source":"https://apps.sos.wv.gov/elections/2026GeneralSampleBallots/SAMPLE%20-%20WV%20Wood%20261103%20General%20-%2014inch.pdf","guide":"https://sos.wv.gov/article/secretary-warner-issues-public-notice-proposed-amendment-west-virginia-constitution-will"}]},"WY":{"has":true,"by":"Wyoming Secretary of State","read":"2026-10-19","list":{"url":"https://sos.wyo.gov/Elections/Docs/2026/2026_Statewide_Ballot_Propositions.pdf","title":"2026 General Election Statewide Ballot Propositions (Wyoming Secretary of State)"},"guide":{"url":"https://sos.wyo.gov/Elections/Docs/2026/2026_Voter_Guide.pdf","title":"2026 Wyoming Voter's Guide (Wyoming Secretary of State, Elections Division)"},"measures":[{"designation":"Proposed Initiative Proposition Number One","title":"People's Initiative to Limit Property Tax in Wyoming through a Homeowner's Property Exemption","text":"Shall a law be enacted: Establishing a property tax exemption for qualified homeowners' primary residence in the amount of fifty percent (50%) of the assessed value of the dwelling; AND Defining \"homeowner\" and \"primary residence\"; providing that no more than one exemption shall apply to a single property or be claimed by a single owner per year; requiring a homeowner to be a resident of Wyoming for at least one year and to have occupied the primary residence for at least six months of the previous tax year to qualify; requiring an initial sworn claim to be filed with the county assessor by the fourth Monday in May; providing for continuing the exemption in subsequent years through annually confirming eligibility; providing a penalty for false claims; clarifying that the exemption applies to the residential structure; and specifying applicability?","kind":"Statute","origin":"a citizens' petition","source":"https://sos.wyo.gov/Elections/Docs/2026/2026_Statewide_Ballot_Propositions.pdf","guide":"https://sos.wyo.gov/Elections/Docs/2026/2026_Voter_Guide.pdf"}]}};
